import { useCallback, useEffect, useState } from 'react';
import styles from '../BookingForm.module.css';
import { type TimeSlot, SLOT_LABELS, normalizeTimeSlot } from '../../../utils/timeSlot';
import { validateOptionDateSelection } from '../../../utils/optionDateValidation';
import {
  type OptionDateItem,
  fetchCalendarDays,
  normalizeOptionDate,
  resolveOptionDate,
} from '../../../utils/optionDateApi';
import { REALTIME_DATE_UPDATED_EVENT } from '../../../services/realtimeSync';

const MAX_OPTION_DATES = 3;
const MONTH_NAMES = ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר'];
const COL_HEADERS = ['א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ש'];

function formatDateLocal(date: Date): string {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function formatDisplay(dateStr: string): string {
  const [y, m, d] = dateStr.split('-');
  return `${d}/${m}/${y}`;
}

function getDayOfWeek(dateStr: string): string {
  const days = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];
  return days[new Date(dateStr + 'T12:00:00').getDay()];
}

interface OptionDatePickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (item: OptionDateItem) => void;
  excludeDates: string[];
  eventType: string;
  timeSlot?: TimeSlot;
}

export const OptionDatePickerModal = ({
  isOpen,
  onClose,
  onSelect,
  excludeDates,
  eventType,
  timeSlot,
}: OptionDatePickerModalProps) => {
  const [current, setCurrent] = useState(() => new Date());
  const [days, setDays] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [manualDate, setManualDate] = useState('');
  const [manualError, setManualError] = useState('');
  const [manualAdding, setManualAdding] = useState(false);
  const [selectingDate, setSelectingDate] = useState<string | null>(null);
  const [pickerError, setPickerError] = useState('');

  const todayStr = formatDateLocal(new Date());

  const loadMonthDays = useCallback(async () => {
    const year = current.getFullYear();
    const month = current.getMonth();
    const start = formatDateLocal(new Date(year, month, 1));
    const end = formatDateLocal(new Date(year, month + 1, 0));

    setLoading(true);
    try {
      const data = await fetchCalendarDays(start, end, eventType);
      setDays(data);
    } catch {
      setDays([]);
    } finally {
      setLoading(false);
    }
  }, [current, eventType]);

  useEffect(() => {
    if (!isOpen) return;
    setManualDate('');
    setManualError('');
    setPickerError('');
    loadMonthDays();
  }, [isOpen, loadMonthDays]);

  useEffect(() => {
    if (!isOpen) return;
    const refresh = () => { loadMonthDays(); };
    window.addEventListener(REALTIME_DATE_UPDATED_EVENT, refresh);
    return () => { window.removeEventListener(REALTIME_DATE_UPDATED_EVENT, refresh); };
  }, [isOpen, loadMonthDays]);

  if (!isOpen) return null;

  const year = current.getFullYear();
  const month = current.getMonth();
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const serverMap = new Map(days.map((d: any) => [d.date, d]));

  const cells: (null | { date: string; hebrewDate: string; disabled: boolean; reason?: string })[] = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let day = 1; day <= daysInMonth; day++) {
    const date = formatDateLocal(new Date(year, month, day));
    const srv = serverMap.get(date);
    const validationError = timeSlot
      ? validateOptionDateSelection(date, srv, timeSlot, excludeDates)
      : 'יש לבחור זמן ביום לפני בחירת תאריך.';
    const disabled = !!validationError;
    cells.push({
      date,
      hebrewDate: srv?.hebrewDate ?? '',
      disabled,
      reason: validationError || undefined,
    });
  }

  const handleManualAdd = async () => {
    setManualError('');
    setManualAdding(true);
    const result = await resolveOptionDate(manualDate, eventType, excludeDates, timeSlot);
    setManualAdding(false);
    if (!result.ok) {
      setManualError(result.error);
      loadMonthDays();
      return;
    }
    onSelect(result.item);
    onClose();
  };

  const handleCalendarSelect = async (cell: { date: string; hebrewDate: string }) => {
    if (selectingDate) return;
    setPickerError('');
    setSelectingDate(cell.date);
    const result = await resolveOptionDate(cell.date, eventType, excludeDates, timeSlot);
    setSelectingDate(null);
    if (!result.ok) {
      setPickerError(result.error);
      loadMonthDays();
      return;
    }
    onSelect(result.item);
    onClose();
  };

  return (
    <div className={styles.optionPickerOverlay} onClick={onClose}>
      <div className={styles.optionPickerModal} onClick={e => e.stopPropagation()}>
        <div className={styles.optionPickerHeader}>
          <h4>בחירת תאריך לאופציה</h4>
          <button type="button" className={styles.optionPickerClose} onClick={onClose}>✕</button>
        </div>

        <div className={styles.optionPickerManual}>
          <label className={styles.optionPickerManualLabel}>הזנה ידנית</label>
          <div className={styles.optionDatesAddRow}>
            <input
              type="date"
              className={styles.optionManualInput}
              value={manualDate}
              min={todayStr}
              onChange={e => {
                setManualDate(e.target.value);
                setManualError('');
              }}
            />
            <button
              type="button"
              className={styles.optionManualAddBtn}
              onClick={handleManualAdd}
              disabled={!manualDate || manualAdding}
            >
              {manualAdding ? 'בודק...' : 'הוסף'}
            </button>
          </div>
          {manualError && <p className={styles.optionManualError}>{manualError}</p>}
        </div>

        <p className={styles.optionPickerOr}>או בחרי מהלוח</p>

        <div className={styles.optionPickerNav}>
          <button type="button" onClick={() => setCurrent(new Date(year, month + 1, 1))}>‹</button>
          <span>{MONTH_NAMES[month]} {year}</span>
          <button type="button" onClick={() => setCurrent(new Date(year, month - 1, 1))}>›</button>
        </div>
        {loading ? (
          <p className={styles.optionPickerLoading}>טוען...</p>
        ) : (
          <>
            {pickerError && <p className={styles.optionManualError}>{pickerError}</p>}
            <div className={styles.optionPickerWeekdays}>
              {COL_HEADERS.map(d => <span key={d}>{d}</span>)}
            </div>
            <div className={styles.optionPickerGrid}>
              {cells.map((cell, idx) =>
                cell ? (
                  <button
                    key={cell.date}
                    type="button"
                    disabled={cell.disabled || selectingDate === cell.date}
                    title={cell.reason}
                    className={`${styles.optionPickerDay} ${cell.disabled ? styles.optionPickerDayDisabled : ''}`}
                    onClick={() => handleCalendarSelect(cell)}
                  >
                    <span className={styles.optionPickerDayNum}>
                      {selectingDate === cell.date ? '…' : new Date(cell.date + 'T12:00:00').getDate()}
                    </span>
                    {cell.hebrewDate && <span className={styles.optionPickerDayHeb}>{cell.hebrewDate}</span>}
                  </button>
                ) : (
                  <span key={`empty-${idx}`} className={styles.optionPickerDayEmpty} />
                )
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

interface OptionDatesBarProps {
  selectedDates: OptionDateItem[];
  onChange: (dates: OptionDateItem[]) => void;
  eventType: string;
  timeSlot?: TimeSlot | string;
  slotWarning?: string;
}

const OptionDatesBar = ({ selectedDates, onChange, eventType, timeSlot: timeSlotProp, slotWarning }: OptionDatesBarProps) => {
  const resolvedSlot = normalizeTimeSlot(timeSlotProp as string);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [manualDate, setManualDate] = useState('');
  const [manualError, setManualError] = useState('');
  const [manualAdding, setManualAdding] = useState(false);
  const normalized = selectedDates.map(normalizeOptionDate);
  const canAdd = normalized.length < MAX_OPTION_DATES && !!resolvedSlot;
  const todayStr = formatDateLocal(new Date());
  const slotLabel = resolvedSlot ? SLOT_LABELS[resolvedSlot] : '';

  const removeDate = (date: string) => {
    if (normalized.length <= 1) {
      alert('חייב להישאר לפחות תאריך אחד באופציה.');
      return;
    }
    onChange(normalized.filter(d => d.date !== date));
  };

  const addDate = (item: OptionDateItem) => {
    if (normalized.some(d => d.date === item.date)) return;
    onChange([...normalized, item]);
    setManualDate('');
    setManualError('');
  };

  const handleManualAdd = async () => {
    setManualError('');
    setManualAdding(true);
    const result = await resolveOptionDate(
      manualDate,
      eventType,
      normalized.map(d => d.date),
      resolvedSlot
    );
    setManualAdding(false);
    if (!result.ok) {
      setManualError(result.error);
      return;
    }
    addDate(result.item);
  };

  return (
    <>
      <div className={styles.optionDatesBar}>
        <div className={styles.optionDatesBarHead}>
          <strong>תאריכי האופציה ({normalized.length}/{MAX_OPTION_DATES})</strong>
          <span className={styles.optionDatesBarHint}>
            {resolvedSlot
              ? `ניתן לשמור עד 3 תאריכים · משבצת ${slotLabel}`
              : 'יש לבחור זמן ביום (בוקר / צהריים / ערב) לפני הוספת תאריכים'}
          </span>
        </div>

        <div className={styles.optionDatesChips}>
          {normalized.map((d, i) => (
            <div key={d.date} className={styles.optionDateChip}>
              <span className={styles.optionDateChipMain}>
                <span className={styles.optionDateChipIndex}>תאריך {i + 1}</span>
                <span className={styles.optionDateChipGreg}>{formatDisplay(d.date)}</span>
                <span className={styles.optionDateChipDow}>יום {getDayOfWeek(d.date)}</span>
                {d.hebrewDate && <span className={styles.optionDateChipHeb}>{d.hebrewDate}</span>}
              </span>
              {normalized.length > 1 && (
                <button type="button" className={styles.optionDateChipRemove} onClick={() => removeDate(d.date)} aria-label="הסר תאריך">
                  ✕
                </button>
              )}
            </div>
          ))}
        </div>

        {slotWarning && <p className={styles.optionManualError}>{slotWarning}</p>}

        {canAdd ? (
          <div className={styles.optionDatesAddSection}>
            <div className={styles.optionDatesAddRow}>
              <button type="button" className={styles.optionAddDateBtn} onClick={() => setPickerOpen(true)}>
                + בחירה מלוח שנה
              </button>
              <span className={styles.optionDatesOr}>או</span>
              <input
                type="date"
                className={styles.optionManualInput}
                value={manualDate}
                min={todayStr}
                onChange={e => {
                  setManualDate(e.target.value);
                  setManualError('');
                }}
              />
              <button
                type="button"
                className={styles.optionManualAddBtn}
                onClick={handleManualAdd}
                disabled={!manualDate || manualAdding}
              >
                {manualAdding ? 'בודק...' : 'הוסף ידנית'}
              </button>
            </div>
            {manualError && <p className={styles.optionManualError}>{manualError}</p>}
          </div>
        ) : normalized.length >= MAX_OPTION_DATES ? (
          <p className={styles.optionDatesMaxMsg}>נבחרו 3 תאריכים — מקסימום לאופציה.</p>
        ) : (
          <p className={styles.optionDatesMaxMsg}>בחרי משבצת זמן ביום לפני הוספת תאריך.</p>
        )}
      </div>

      <OptionDatePickerModal
        isOpen={pickerOpen}
        onClose={() => setPickerOpen(false)}
        onSelect={addDate}
        excludeDates={normalized.map(d => d.date)}
        eventType={eventType}
        timeSlot={resolvedSlot ?? undefined}
      />
    </>
  );
};

export default OptionDatesBar;

import React, { useState } from 'react';
import CheckCamera from '../../CheckCamera/CheckCamera';
import CheckDetailsForm from '../../CheckDetailsForm/CheckDetailsForm';
import type { DepositCheckDetails } from '../../../utils/checkOcr';
import { openContractPdf, printContract } from '../../../utils/contractPrint';
import type { PaymentTermsTemplate } from '../../../utils/paymentTerms';

interface PaymentAndUpgradesSectionProps {
  formData: any;
  handleChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => void;
  isHallOnly: boolean;
  isOption?: boolean;
  depositMethod: string;
  setDepositMethod: (method: string) => void;
  checkScanning: boolean;
  onCheckCapture: (imageSrc: string) => void | Promise<void>;
  onCheckFileUpload: (e: React.ChangeEvent<HTMLInputElement>) => void | Promise<void>;
  onDeleteCheck: () => void;
  onCheckDetailsChange: (details: DepositCheckDetails) => void;
  totals: {
    mainBase: number;
    hallExtrasBase: number;
    externalExtrasBase: number;
    discountVal: number;
    mainVat: number;
    hallExtrasVat: number;
    externalExtrasVat: number;
    baseTotal: number;
    hallExtrasTotal: number;
    externalExtrasTotal: number;
    hallTotal: number;
    finalTotal: number;
  };
  isFoodRelevant: boolean;
  kosherType: string;
  isEditMode: boolean;
  editId?: string;
  errors?: Record<string, string>;
  vatRate?: number;
  paymentTemplates: PaymentTermsTemplate[];
  paymentTemplateId: string;
  onPaymentTemplateChange: (templateId: string) => void;
  paymentTermsCustom: boolean;
  onPaymentTermsCustomChange: (custom: boolean) => void;
  paymentTermsText: string;
  onPaymentTermsTextChange: (text: string) => void;
  eventDate?: string | null;
  easycountMeta?: {
    mode?: string;
    label?: string;
    canIssueRealDocuments?: boolean;
  } | null;
}

const PaymentAndUpgradesSection = ({
  formData,
  handleChange,
  isHallOnly,
  isOption = false,
  depositMethod,
  setDepositMethod,
  checkScanning,
  onCheckCapture,
  onCheckFileUpload,
  onDeleteCheck,
  onCheckDetailsChange,
  totals,
  isFoodRelevant,
  isEditMode,
  editId,
  errors,
  vatRate = 17,
  paymentTemplates,
  paymentTemplateId,
  onPaymentTemplateChange,
  paymentTermsCustom,
  onPaymentTermsCustomChange,
  paymentTermsText,
  onPaymentTermsTextChange,
  eventDate,
  easycountMeta,
}: PaymentAndUpgradesSectionProps) => {
  const [editingCustomPayment, setEditingCustomPayment] = useState(false);
  const [customDraft, setCustomDraft] = useState('');

  const openCustomEditor = () => {
    setCustomDraft(paymentTermsCustom ? paymentTermsText : '');
    setEditingCustomPayment(true);
  };

  const saveCustomPayment = () => {
    const text = customDraft.trim();
    if (!text) {
      alert('יש להזין נוסח תשלום');
      return;
    }
    onPaymentTermsCustomChange(true);
    onPaymentTermsTextChange(text);
    setEditingCustomPayment(false);
  };

  const cancelCustomEditor = () => {
    setEditingCustomPayment(false);
    setCustomDraft('');
  };

  const isCheckDeposit = depositMethod === 'check_upload' || depositMethod === 'check_capture';
  const hasCheckImage = !!formData.depositCheckUrl;

  return (
    <div className="card mb-3">
      <div className="card-header maple-section-header">סיכום, פיקדון ותשלום</div>
      <div className="card-body">
          {!isOption && easycountMeta && (
            <div className={`alert ${easycountMeta.canIssueRealDocuments ? 'alert-success' : 'alert-warning'} mb-3`}>
              <strong>EZCount:</strong> {easycountMeta.label || 'סימולציה — לא מופקות קבלות אמיתיות'}
              {!easycountMeta.canIssueRealDocuments && (
                <span> · ניתן להזין מקדמה לתיעוד במערכת, בלי הפקת מסמך מס אמיתי.</span>
              )}
            </div>
          )}

          {!isOption && (
            <div className="mb-3">
              <label className="form-label fw-semibold">סכום מקדמה שנגבתה (₪)</label>
              <input
                type="number"
                name="advancePaid"
                value={formData.advancePaid ?? ''}
                onChange={handleChange}
                className="form-control"
                placeholder="0"
                min={0}
                step="any"
              />
              <div className="form-text">אם הוזן סכום — המערכת תייצר קבלה (בסימולציה עד חיבור EZCount).</div>
            </div>
          )}

          {isHallOnly && (
            <div className="p-3 mb-3 rounded border border-success bg-success-subtle">
              <label className="form-label fw-bold text-success">מחיר השכרת אולם (₪){!isOption ? ' *' : ''}</label>
              <input
                type="number"
                name="hallRentalPrice"
                value={formData.hallRentalPrice || ''}
                onChange={handleChange}
                className={`form-control form-control-lg fw-bold ${errors?.hallRentalPrice ? 'is-invalid' : ''}`}
                placeholder="הזן סכום לשכירות האולם (ללא אוכל)..."
                required={isHallOnly && !isOption}
                min={1}
                step="any"
              />
              {errors?.hallRentalPrice && (
                <div className="invalid-feedback">{errors.hallRentalPrice}</div>
              )}
            </div>
          )}

          <div className="row g-3 mb-3">
            <div className="col-md-4">
              <label className="form-label">הנחה כוללת (%)</label>
              <input type="number" name="discountPercent" value={formData.discountPercent} onChange={handleChange} className="form-control" placeholder="0" />
            </div>
            <div className="col-md-4">
              <label className="form-label">הנחה בשקלים (₪)</label>
              <input type="number" name="discountAmount" value={formData.discountAmount} onChange={handleChange} className="form-control" placeholder="0" />
            </div>
            <div className="col-md-4">
              <label className="form-label">הגדרת מע&quot;מ ({vatRate}%)</label>
              <div className="d-flex flex-wrap gap-3 mt-1">
                <div className="form-check">
                  <input type="radio" className="form-check-input" name="vatType" id="vat-not-included" value="not_included" checked={formData.vatType === 'not_included'} onChange={handleChange} />
                  <label className="form-check-label" htmlFor="vat-not-included">לא כולל מע&quot;מ</label>
                </div>
                <div className="form-check">
                  <input type="radio" className="form-check-input" name="vatType" id="vat-included" value="included" checked={formData.vatType === 'included'} onChange={handleChange} />
                  <label className="form-check-label" htmlFor="vat-included">כולל מע&quot;מ</label>
                </div>
              </div>
            </div>
          </div>

          <div className="d-flex flex-wrap gap-3 mb-3">
            <div className="form-check">
              <input type="radio" className="form-check-input" name="deposit" id="deposit-credit" value="credit_card" checked={depositMethod === 'credit_card'} onChange={(e) => setDepositMethod(e.target.value)} />
              <label className="form-check-label" htmlFor="deposit-credit">תשלום באשראי / מזומן</label>
            </div>
            <div className="form-check">
              <input type="radio" className="form-check-input" name="deposit" id="deposit-upload" value="check_upload" checked={depositMethod === 'check_upload'} onChange={(e) => setDepositMethod(e.target.value)} />
              <label className="form-check-label" htmlFor="deposit-upload">העלאת צילום צ&apos;ק פיקדון</label>
            </div>
            <div className="form-check">
              <input type="radio" className="form-check-input" name="deposit" id="deposit-capture" value="check_capture" checked={depositMethod === 'check_capture'} onChange={(e) => setDepositMethod(e.target.value)} />
              <label className="form-check-label fw-semibold" htmlFor="deposit-capture">📸 צילום צ&apos;ק כעת</label>
            </div>
          </div>

          {isCheckDeposit && (
            <div className="border rounded p-3 mb-3">
              <label className="form-label fw-semibold">תמונת צ&apos;ק פיקדון</label>

              {depositMethod === 'check_capture' && !hasCheckImage && (
                <CheckCamera
                  disabled={checkScanning}
                  onCapture={onCheckCapture}
                  onRetake={onDeleteCheck}
                />
              )}

              {(depositMethod === 'check_upload' || hasCheckImage) && (
                <div className={depositMethod === 'check_capture' && hasCheckImage ? 'mt-3' : ''}>
                  {depositMethod === 'check_upload' && !hasCheckImage && (
                    <input type="file" accept="image/*" onChange={onCheckFileUpload} className="form-control" />
                  )}
                  {hasCheckImage && (
                    <div className="d-flex align-items-center gap-2 flex-wrap mb-2">
                      <span className="text-success fw-semibold">✓ צ&apos;ק צולם/צורף בהצלחה</span>
                      <button type="button" onClick={onDeleteCheck} className="btn btn-sm btn-outline-danger">
                        🗑️ מחק
                      </button>
                    </div>
                  )}
                </div>
              )}

              {(hasCheckImage || formData.depositCheckDetails) && (
                <CheckDetailsForm
                  details={formData.depositCheckDetails || {}}
                  imageUrl={formData.depositCheckUrl || undefined}
                  scanning={checkScanning}
                  onChange={onCheckDetailsChange}
                />
              )}
            </div>
          )}

          <div className="mb-3">
            <label className="form-label fw-bold">תנאי תשלום לחוזה</label>
            <select
              className="form-select"
              value={paymentTemplateId}
              onChange={(e) => {
                onPaymentTermsCustomChange(false);
                setEditingCustomPayment(false);
                onPaymentTemplateChange(e.target.value);
              }}
            >
              {paymentTemplates.map((t) => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>

            <div className="d-flex align-items-center gap-2 flex-wrap mt-2">
              <span className="text-secondary">נוסח מותאם אישית לאירוע זה</span>
              <button
                type="button"
                onClick={openCustomEditor}
                title="עריכת נוסח מותאם לאירוע זה"
                aria-label="עריכת נוסח מותאם לאירוע זה"
                className={`btn btn-sm ${paymentTermsCustom ? 'btn-primary' : 'btn-outline-primary'}`}
              >
                ✏️
              </button>
              {paymentTermsCustom && (
                <span className="badge text-bg-success">נוסח מותאם שמור לאירוע זה</span>
              )}
            </div>

            {editingCustomPayment && (
              <div className="border border-primary rounded p-3 mt-2 bg-white">
                <label className="form-label fw-semibold">
                  הקלידי נוסח תשלום ייחודי — יישמר רק לאירוע זה
                </label>
                <textarea
                  className="form-control"
                  rows={4}
                  value={customDraft}
                  onChange={(e) => setCustomDraft(e.target.value)}
                  placeholder="לדוגמה: 70% עד שבוע לפני האירוע, 30% בצ'ק לאחר האירוע..."
                  autoFocus
                />
                <div className="d-flex gap-2 mt-2">
                  <button type="button" onClick={saveCustomPayment} className="btn btn-primary btn-sm">
                    שמירה לאירוע זה
                  </button>
                  <button type="button" onClick={cancelCustomEditor} className="btn btn-outline-secondary btn-sm">
                    ביטול
                  </button>
                </div>
              </div>
            )}

            <div className={`p-3 mt-2 rounded border ${paymentTermsCustom ? 'border-success bg-success-subtle text-success' : 'border-info bg-info-subtle text-info-emphasis'}`}>
              <strong className="d-block mb-1">
                {paymentTermsCustom ? 'נוסח שיופיע בחוזה (מותאם):' : 'תצוגה מקדימה — יופיע בחוזה:'}
              </strong>
              {paymentTermsText || 'בחרי תבנית או לחצי על העיפרון לנוסח מותאם'}
              {eventDate && !paymentTermsCustom && (
                <div className="small mt-1">מחושב לפי תאריך האירוע: {eventDate}</div>
              )}
            </div>
          </div>

          {isEditMode && editId && (
            <div className="d-flex gap-2 flex-wrap mb-3">
              <button type="button" onClick={() => void openContractPdf(editId)} className="btn btn-success">
                צפייה בחוזה
              </button>
              <button
                type="button"
                onClick={async () => {
                  try {
                    await printContract(editId);
                  } catch (e) {
                    alert(e instanceof Error ? e.message : 'לא הצלחנו להדפיס את החוזה. ודאי שמדפסת מחוברת ונסי שוב.');
                  }
                }}
                className="btn btn-primary"
              >
                הדפסת חוזה
              </button>
            </div>
          )}

          <div className="maple-price-summary p-3">
            <h5 className="mb-3">סיכום תשלומים</h5>

            <div className="mb-3">
              <strong className="d-block mb-1">תשלום בסיסי (אירוע)</strong>
              <div className="d-flex flex-column gap-1 small">
                <span>ביניים: ₪{totals.mainBase.toLocaleString()}</span>
                {totals.discountVal > 0 && <span className="text-danger">הנחות: -₪{totals.discountVal.toLocaleString()}</span>}
                {totals.mainVat > 0 && <span>מע&quot;מ: ₪{totals.mainVat.toLocaleString()}</span>}
                <span className="fw-bold">₪{totals.baseTotal.toLocaleString()}</span>
              </div>
            </div>

            <div className="mb-3">
              <strong className="d-block mb-1">תשלום תוספות (לאולם)</strong>
              <div className="d-flex flex-column gap-1 small">
                <span>כשרות + קבלת פנים + מאבטח: ₪{totals.hallExtrasBase.toLocaleString()}</span>
                {totals.hallExtrasVat > 0 && <span>מע&quot;מ: ₪{totals.hallExtrasVat.toLocaleString()}</span>}
                <span className="fw-bold">₪{totals.hallExtrasTotal.toLocaleString()}</span>
              </div>
            </div>

            {totals.externalExtrasBase > 0 && (
              <div className="mb-3">
                <strong className="d-block mb-1">תשלום לספקים חיצוניים</strong>
                <div className="d-flex flex-column gap-1 small">
                  <span>שדרוגים: ₪{totals.externalExtrasBase.toLocaleString()}</span>
                  {totals.externalExtrasVat > 0 && <span>מע&quot;מ: ₪{totals.externalExtrasVat.toLocaleString()}</span>}
                  <span className="fw-bold">₪{totals.externalExtrasTotal.toLocaleString()}</span>
                  <span className="text-muted">תשלום ישיר לספק — לא כולל בצ&apos;ק לאולם</span>
                </div>
              </div>
            )}

            <p className="fs-5 fw-bold mb-1">סה&quot;כ הצעה: ₪ {totals.finalTotal.toLocaleString()}</p>
            {isFoodRelevant && formData.guestCount && (
              <p className="small text-muted mb-0">
                {formData.guestCount} מנות בתשלום
                {formData.optionalGuestCount ? ` + ${formData.optionalGuestCount} רזרבה (ללא חיוב)` : ''}
              </p>
            )}
          </div>
        </div>
      </div>
  );
};

export default PaymentAndUpgradesSection;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { calendarKeyFromDbDate } from '../../utils/dateLocal';
import { formatTimeOfDayDisplay } from '../../utils/timeSlot';
import { parseNotes, parseNotesBundle } from '../../utils/notesStorage';
import { openContractPdf, printContract } from '../../utils/contractPrint';
import {
  canForceReissueEasyCountReceipt,
  canRetryEasyCountReceipt,
  formatEasyCountStatusLabel,
} from '../../utils/easycount';
import { apiFetch } from '../../services/api';
import { API_URL } from '../../config/api';
import { canEditBooking } from '../../utils/bookingEdit';
import { NotesList } from '../NotesList/NotesList';
import HallInvoicesPanel from './HallInvoicesPanel';
import styles from './BookingsManager.module.css';

interface BookingDetailsModalProps {
  booking: any;
  onClose: () => void;
  onBookingUpdated?: (booking: any) => void;
}

const BookingDetailsModal = ({ booking, onClose, onBookingUpdated }: BookingDetailsModalProps) => {
  const navigate = useNavigate();
  const [issuingReceipt, setIssuingReceipt] = useState(false);

  const eventDateStr = booking.eventDate?.date
    ? calendarKeyFromDbDate(new Date(booking.eventDate.date))
    : '';
  const dateDisplay = booking.eventDate?.date
    ? new Date(booking.eventDate.date).toLocaleDateString('he-IL')
    : '';
  const editable = eventDateStr ? canEditBooking(eventDateStr) : false;
  const isWedding = booking.eventType === 'חתונה';
  const isHallOnly = booking.eventType === 'השכרת אולם בלי אוכל';
  const clientNotes = parseNotesBundle(booking.clientComments);
  const managerNotes = parseNotes(booking.managerComments);
  const showRetry = canRetryEasyCountReceipt(booking);
  const showForceReissue = canForceReissueEasyCountReceipt(booking);

  const handleEdit = () => {
    onClose();
    navigate(`/booking/edit/${booking.id}`);
  };

  const handleIssueReceipt = async (force = false) => {
    setIssuingReceipt(true);
    try {
      const res = await apiFetch(`${API_URL}/bookings/${booking.id}/easycount-receipt`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ force }),
      });
      const json = await res.json();
      alert(json.message || (json.success ? 'קבלה הופקה בהצלחה' : 'שגיאה בהפקת קבלה'));
      if (json.success && json.data && onBookingUpdated) {
        onBookingUpdated(json.data);
      }
    } catch {
      alert('שגיאת תקשורת עם השרת');
    } finally {
      setIssuingReceipt(false);
    }
  };

  return (
    <div className={styles.popupOverlay} onClick={onClose}>
      <div className={`${styles.popupBox} ${styles.detailsBox}`} onClick={e => e.stopPropagation()}>
        <div className={styles.popupHeader}>
          <span>
            פרטי הזמנה
            {booking.eventCode && ` #${booking.eventCode}`}
            {dateDisplay && ` · ${dateDisplay}`}
          </span>
          <button type="button" className={styles.popupClose} onClick={onClose}>✕</button>
        </div>

        <div className={styles.popupBody}>
          <section className={styles.detailsSection}>
            <h3 className={styles.sectionTitle}>פרטי האירוע</h3>
            <div className={styles.popupRow}><label>קוד אירוע:</label><span>{booking.eventCode || '—'}</span></div>
            <div className={styles.popupRow}><label>תאריך:</label><span>{dateDisplay || '—'}</span></div>
            <div className={styles.popupRow}><label>סוג אירוע:</label><span>{booking.eventType || '—'}</span></div>
            <div className={styles.popupRow}><label>מועד:</label><span>{formatTimeOfDayDisplay(booking.timeOfDay)}</span></div>
            {booking.leadSource && (
              <div className={styles.popupRow}><label>מקור ליד:</label><span>{booking.leadSource}</span></div>
            )}
          </section>

          <section className={styles.detailsSection}>
            <h3 className={styles.sectionTitle}>צד א'</h3>
            <div className={styles.popupRow}><label>שם:</label><span>{booking.clientAFullName || '—'}</span></div>
            <div className={styles.popupRow}><label>ת.ז:</label><span>{booking.clientAIdNumber || '—'}</span></div>
            <div className={styles.popupRow}><label>טלפון:</label><span>{booking.clientAPhone || '—'}</span></div>
            <div className={styles.popupRow}><label>אימייל:</label><span>{booking.clientAEmail || '—'}</span></div>
            <div className={styles.popupRow}><label>כתובת:</label><span>{booking.clientAAddress || '—'}</span></div>
          </section>

          {(isWedding || booking.clientBFullName) && (
            <section className={styles.detailsSection}>
              <h3 className={styles.sectionTitle}>צד ב'</h3>
              <div className={styles.popupRow}><label>שם:</label><span>{booking.clientBFullName || '—'}</span></div>
              <div className={styles.popupRow}><label>ת.ז:</label><span>{booking.clientBIdNumber || '—'}</span></div>
              <div className={styles.popupRow}><label>טלפון:</label><span>{booking.clientBPhone || '—'}</span></div>
              <div className={styles.popupRow}><label>אימייל:</label><span>{booking.clientBEmail || '—'}</span></div>
              <div className={styles.popupRow}><label>כתובת:</label><span>{booking.clientBAddress || '—'}</span></div>
            </section>
          )}

          <section className={styles.detailsSection}>
            <h3 className={styles.sectionTitle}>פרטי עסקה</h3>
            {isHallOnly ? (
              <div className={styles.popupRow}>
                <label>מחיר השכרה:</label>
                <span>₪{booking.hallRentalPrice?.toLocaleString() || 0}</span>
              </div>
            ) : (
              <>
                <div className={styles.popupRow}><label>מוזמנים:</label><span>{booking.guestCount ?? '—'}</span></div>
                <div className={styles.popupRow}><label>מחיר מנה:</label><span>₪{booking.finalPricePortion ?? 0}</span></div>
              </>
            )}
            <div className={styles.popupRow}>
              <label>תשלום בסיסי:</label>
              <span>₪{(booking.basePrice ?? booking.totalPrice)?.toLocaleString() ?? 0}</span>
            </div>
            {(booking.extrasPrice ?? 0) > 0 && (
              <div className={styles.popupRow}>
                <label>תוספות לאולם:</label>
                <span>₪{booking.extrasPrice?.toLocaleString() ?? 0}</span>
              </div>
            )}
            {(booking.externalExtrasPrice ?? 0) > 0 && (
              <div className={styles.popupRow}>
                <label>ספקים חיצוניים (לידיעה):</label>
                <span>₪{booking.externalExtrasPrice?.toLocaleString() ?? 0}</span>
              </div>
            )}
            {(booking.liveAdditionsTotal ?? 0) > 0 && (
              <div className={styles.popupRow}>
                <label>תוספות בזמן האירוע:</label>
                <span>₪{booking.liveAdditionsTotal?.toLocaleString() ?? 0}</span>
              </div>
            )}
            <div className={styles.popupRow}>
              <label>סה&quot;כ חשבון לאולם:</label>
              <span className={styles.totalPrice}>₪{booking.totalPrice?.toLocaleString() ?? 0}</span>
            </div>
            <div className={styles.popupRow}><label>שולם:</label><span>₪{booking.paidAmount?.toLocaleString() ?? 0}</span></div>
            {booking.advancePaid > 0 && (
              <div className={styles.popupRow}><label>מקדמה:</label><span>₪{booking.advancePaid?.toLocaleString()}</span></div>
            )}
            {booking.totalPaid > 0 && (
              <div className={styles.popupRow}><label>סה"כ שולם:</label><span>₪{booking.totalPaid?.toLocaleString()}</span></div>
            )}
            <div className={styles.popupRow}><label>סטטוס תשלום:</label><span>{booking.paymentStatus || '—'}</span></div>
            {booking.depositMethod && (
              <div className={styles.popupRow}>
                <label>אמצעי תשלום מקדמה:</label>
                <span>
                  {booking.depositMethod === 'credit_card'
                    ? 'אשראי / מזומן'
                    : booking.depositMethod === 'check_capture'
                      ? "צ'ק (צילום)"
                      : booking.depositMethod === 'check_upload'
                        ? "צ'ק (העלאה)"
                        : booking.depositMethod}
                </span>
              </div>
            )}
            {(booking.advancePaid ?? 0) > 0 && (
              <div className={styles.popupRow}>
                <label>EZCount:</label>
                <span>{formatEasyCountStatusLabel(booking.easycountStatus)}</span>
              </div>
            )}
            {booking.easycountDocId && (
              <div className={styles.popupRow}>
                <label>מזהה קבלה:</label>
                <span>{booking.easycountDocId}</span>
              </div>
            )}
            {booking.easycountError && (
              <div className={styles.popupRow}>
                <label>שגיאת EZCount:</label>
                <span style={{ color: '#b91c1c' }}>{booking.easycountError}</span>
              </div>
            )}
            {booking.easycountDocUrl && (
              <div className={styles.popupRow}>
                <label>קישור קבלה:</label>
                <span>
                  <a href={booking.easycountDocUrl} target="_blank" rel="noreferrer">פתיחת PDF</a>
                </span>
              </div>
            )}
            {(showRetry || showForceReissue) && (
              <div className={styles.popupRow} style={{ marginTop: '8px', gap: '8px', flexWrap: 'wrap' }}>
                {showRetry && (
                  <button
                    type="button"
                    className={styles.btnSecondary}
                    disabled={issuingReceipt}
                    onClick={() => handleIssueReceipt(false)}
                  >
                    {issuingReceipt ? 'מפיקה קבלה...' : 'הפק/י קבלה מחדש'}
                  </button>
                )}
                {showForceReissue && (
                  <button
                    type="button"
                    className={styles.btnSecondary}
                    disabled={issuingReceipt}
                    onClick={() => {
                      if (window.confirm('להפיק קבלה חדשה? פעולה זו מתאימה למעבר מסימולציה ל-EZCount אמיתי.')) {
                        handleIssueReceipt(true);
                      }
                    }}
                  >
                    הפקה מחדש (Force)
                  </button>
                )}
              </div>
            )}

            <HallInvoicesPanel bookingId={booking.id} isOption={booking.isOption} />

            <div className={styles.popupRow}><label>מוזיקה:</label><span>{booking.hasMusic ? 'כן' : 'לא'}</span></div>
            {booking.akumApprovalCode && (
              <div className={styles.popupRow}><label>קוד ע.ח:</label><span>{booking.akumApprovalCode}</span></div>
            )}
            <div className={styles.popupRow}><label>חוזה נחתם:</label><span>{booking.isContractSigned ? 'כן' : 'לא'}</span></div>
            <div className={styles.popupRow}><label>בדיקת אבטחה:</label><span>{booking.securityCheckStatus || '—'}</span></div>
            <div className={styles.popupRow}><label>נציג:</label><span>{booking.createdBy || '—'}</span></div>
            {booking.updatedBy && (
              <div className={styles.popupRow}><label>עודכן ע"י:</label><span>{booking.updatedBy}</span></div>
            )}
            {booking.createdAt && (
              <div className={styles.popupRow}>
                <label>נוצר:</label>
                <span>{new Date(booking.createdAt).toLocaleString('he-IL')}</span>
              </div>
            )}
          </section>

          {(managerNotes.length > 0 || clientNotes.menu.length > 0 || clientNotes.internal.length > 0) && (
            <section className={styles.detailsSection}>
              <h3 className={styles.sectionTitle}>הערות</h3>
              {managerNotes.length > 0 && (
                <div className={styles.notesBlock}>
                  <strong>הערות מנהל:</strong>
                  <NotesList notes={managerNotes} />
                </div>
              )}
              {clientNotes.menu.length > 0 && (
                <div className={styles.notesBlock}>
                  <strong>הערות לתפריט:</strong>
                  <NotesList notes={clientNotes.menu} />
                </div>
              )}
              {clientNotes.internal.length > 0 && (
                <div className={styles.notesBlock}>
                  <strong>הערות פנימיות:</strong>
                  <NotesList notes={clientNotes.internal} />
                </div>
              )}
            </section>
          )}

          {booking.additions?.length > 0 && (
            <section className={styles.detailsSection}>
              <h3 className={styles.sectionTitle}>תוספות במהלך האירוע</h3>
              {booking.additions.map((add: any) => (
                <div key={add.id} className={styles.additionItem}>
                  <div className={styles.additionMeta}>
                    🕒 {new Date(add.createdAt).toLocaleString('he-IL', { dateStyle: 'short', timeStyle: 'short' })}
                  </div>
                  <div><strong>פירוט:</strong> <span>{add.description}</span></div>
                  <div><strong>עלות:</strong> ₪{add.cost} (אחראי: {add.staffName})</div>
                  {add.signature && (
                    <div className={styles.signatureBlock}>
                      <span>חתימת לקוח:</span>
                      <img src={add.signature} alt="חתימת לקוח" className={styles.signatureImg} />
                    </div>
                  )}
                </div>
              ))}
            </section>
          )}

          <div className={styles.detailsActions}>
            <button
              type="button"
              className={styles.btnPrimary}
              disabled={!editable}
              title={editable ? 'עריכת פרטי ההזמנה' : 'לא ניתן לערוך ביום האירוע או לאחריו'}
              onClick={handleEdit}
            >
              עריכת פרטי ההזמנה
            </button>

            {booking.id && (
              <>
                <button type="button" className={styles.btnSecondary} onClick={() => void openContractPdf(booking.id)}>
                  צפייה בחוזה
                </button>
                <button
                  type="button"
                  className={styles.btnSecondary}
                  onClick={async () => {
                    try {
                      await printContract(booking.id);
                    } catch (e) {
                      alert(e instanceof Error ? e.message : 'לא הצלחנו להדפיס את החוזה.');
                    }
                  }}
                >
                  הדפסת חוזה
                </button>
              </>
            )}

            {booking.isContractSigned && !booking.clientSignatureUrl && (
              <p className={styles.editBlockedMsg}>
                החוזה מסומן כחתום, אך תמונת החתימה חסרה. יש לחתום מחדש בעריכת ההזמנה.
              </p>
            )}

            {!editable && (
              <p className={styles.editBlockedMsg}>לא ניתן לערוך ביום האירוע או לאחריו</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BookingDetailsModal;

import { useEffect, useMemo, useState } from 'react';
import styles from './BookingsManager.module.css';
import BookingDetailsModal from './BookingDetailsModal';
import { useBookingsQuery } from '../../hooks/queries';
import { PageLoader } from '../PageLoader/PageLoader';
import { loadTablePrefs, saveTablePrefs } from '../../utils/tablePrefs';
import {
  PageHeader,
  Input,
  EmptyState,
  SectionHeader,
  DataTable,
  EventCard,
  Badge,
  Button,
  type DataTableColumn,
  type EventCardData,
} from '../ui';

const startOfDay = (d: Date) => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const getEventDay = (b: any) => (b.eventDate?.date ? startOfDay(new Date(b.eventDate.date)) : null);

const dateStr = (b: any) =>
  b.eventDate?.date ? new Date(b.eventDate.date).toLocaleDateString('he-IL') : '—';

const toEventCard = (b: any, status: 'confirmed' | 'past'): EventCardData => ({
  id: b.id,
  date: dateStr(b),
  code: b.eventCode,
  clientName: b.clientAFullName,
  clientNameB: b.clientBFullName,
  eventType: b.eventType,
  timeOfDay: b.timeOfDay,
  guestCount:
    b.eventType === 'השכרת אולם בלי אוכל'
      ? 'השכרת אולם (ללא מנות)'
      : b.guestCount,
  status,
  statusLabel: status === 'confirmed' ? 'מאושר' : 'עבר',
});

const TABLE_ID = 'bookings-manager';

const BookingsManager = () => {
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [selected, setSelected] = useState<any>(null);
  const [sortKey, setSortKey] = useState(() => loadTablePrefs(TABLE_ID).sortColumn ?? 'date');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>(() => loadTablePrefs(TABLE_ID).sortDir ?? 'asc');

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
    }, 300);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    saveTablePrefs(TABLE_ID, { sortColumn: sortKey, sortDir });
  }, [sortKey, sortDir]);

  const handleSort = (key: string) => {
    if (sortKey === key) {
      setSortDir((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  const sortBookings = (bookings: any[]) => {
    const sorted = [...bookings];
    sorted.sort((a, b) => {
      let cmp = 0;
      switch (sortKey) {
        case 'code':
          cmp = String(a.eventCode ?? '').localeCompare(String(b.eventCode ?? ''), 'he');
          break;
        case 'client':
          cmp = String(a.clientAFullName ?? '').localeCompare(String(b.clientAFullName ?? ''), 'he');
          break;
        case 'type':
          cmp = String(a.eventType ?? '').localeCompare(String(b.eventType ?? ''), 'he');
          break;
        case 'guests':
          cmp = (Number(a.guestCount) || 0) - (Number(b.guestCount) || 0);
          break;
        case 'date':
        default: {
          const dayA = getEventDay(a)?.getTime() ?? 0;
          const dayB = getEventDay(b)?.getTime() ?? 0;
          cmp = dayA - dayB;
          break;
        }
      }
      return sortDir === 'asc' ? cmp : -cmp;
    });
    return sorted;
  };

  const { data, isLoading } = useBookingsQuery({
    status: 'BOOKED',
    page: 1,
    limit: 500,
    search: debouncedSearch || undefined,
  });

  const { upcomingBookings, pastBookings } = useMemo(() => {
    const today = startOfDay(new Date());
    const bookings = (data?.data ?? []).filter((b: any) => !b.isOption);

    const upcoming = sortBookings(
      bookings
      .filter((b: any) => {
        const day = getEventDay(b);
        return day !== null && day >= today;
      })
    );

    const past = sortBookings(
      bookings
      .filter((b: any) => {
        const day = getEventDay(b);
        return day !== null && day < today;
      })
    );

    return { upcomingBookings: upcoming, pastBookings: past };
  }, [data, sortKey, sortDir]);

  const closeSelected = () => setSelected(null);

  const columns: DataTableColumn<any>[] = [
    { key: 'date', header: 'תאריך', sortable: true, render: (b) => dateStr(b) },
    { key: 'code', header: 'קוד', sortable: true, render: (b) => (b.eventCode ? `#${b.eventCode}` : '—') },
    { key: 'client', header: 'לקוח', sortable: true, render: (b) => b.clientAFullName },
    { key: 'type', header: 'סוג', sortable: true, render: (b) => b.eventType },
    {
      key: 'guests',
      header: 'מוזמנים',
      sortable: true,
      render: (b) =>
        b.eventType === 'השכרת אולם בלי אוכל' ? '—' : (b.guestCount ?? '—'),
    },
    {
      key: 'status',
      header: 'סטטוס',
      render: (b) => {
        const today = startOfDay(new Date());
        const day = getEventDay(b);
        const isPast = day !== null && day < today;
        return (
          <Badge variant={isPast ? 'past' : 'confirmed'}>
            {isPast ? 'עבר' : 'מאושר'}
          </Badge>
        );
      },
    },
    {
      key: 'actions',
      header: 'פעולות',
      render: (b) => (
        <Button
          variant="secondary"
          size="sm"
          onClick={(e) => {
            e.stopPropagation();
            setSelected(b);
          }}
        >
          פרטים
        </Button>
      ),
    },
  ];

  const renderSection = (
    title: string,
    bookings: any[],
    cardStatus: 'confirmed' | 'past',
  ) => (
    <section className={styles.section}>
      <SectionHeader title={title} count={bookings.length} />
      <div className={styles.tableWrap}>
        <DataTable
          caption={title}
          columns={columns}
          data={bookings}
          rowKey={(b) => b.id}
          onRowClick={(b) => setSelected(b)}
          sortKey={sortKey}
          sortDir={sortDir}
          onSort={handleSort}
        />
      </div>
      <div className={styles.cardsWrap}>
        {bookings.map((b) => (
          <EventCard
            key={b.id}
            event={toEventCard(b, cardStatus)}
            onView={() => setSelected(b)}
            viewLabel="הצגת כל פרטי ההזמנה"
          />
        ))}
      </div>
    </section>
  );

  return (
    <div className={styles.container}>
      <PageHeader title="ניהול הזמנות" subtitle="הזמנות סגורות — קרובות ועברו" />

      <Input
        fieldClassName={styles.searchInput}
        placeholder="חיפוש לפי שם או תעודת זהות..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        aria-label="חיפוש הזמנות"
      />

      {isLoading ? (
        <PageLoader />
      ) : upcomingBookings.length === 0 && pastBookings.length === 0 ? (
        <EmptyState
          icon="📋"
          title={search ? 'לא נמצאו תוצאות' : 'אין הזמנות סגורות'}
          message={search ? 'נסה לחפש בשם אחר או בתעודת זהות' : 'הזמנות חדשות יופיעו כאן לאחר סגירה'}
        />
      ) : (
        <>
          {upcomingBookings.length > 0 &&
            renderSection('אירועים קרובים', upcomingBookings, 'confirmed')}
          {pastBookings.length > 0 &&
            renderSection('אירועים שעברו', pastBookings, 'past')}
        </>
      )}

      {selected && (
        <BookingDetailsModal
          booking={selected}
          onClose={closeSelected}
          onBookingUpdated={setSelected}
        />
      )}
    </div>
  );
};

export default BookingsManager;

