import { useCallback, useEffect, useState } from 'react';
import { apiFetch } from '../../services/api';
import { API_URL } from '../../config/api';

export interface HallInvoiceRow {
  id: string;
  externalId: string;
  amount: number;
  status: string;
  paymentUrl?: string | null;
  installmentLabel?: string | null;
  description?: string | null;
  paidAt?: string | null;
  createdAt: string;
}

interface HallInvoicesPanelProps {
  bookingId: string;
  isOption?: boolean;
  onPaymentUpdated?: () => void;
}

const HallInvoicesPanel = ({ bookingId, isOption, onPaymentUpdated }: HallInvoicesPanelProps) => {
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [hallAmount, setHallAmount] = useState(0);
  const [remaining, setRemaining] = useState(0);
  const [invoices, setInvoices] = useState<HallInvoiceRow[]>([]);
  const [error, setError] = useState('');

  const loadInvoices = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch(`${API_URL}/bookings/${bookingId}/invoices`);
      const json = await res.json();
      if (!json.success) throw new Error(json.message || 'שגיאה בטעינת חשבוניות');
      setHallAmount(json.data.hallAmount ?? 0);
      setRemaining(json.data.remaining ?? 0);
      setInvoices(json.data.invoices ?? []);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'שגיאה בטעינת חשבוניות');
    } finally {
      setLoading(false);
    }
  }, [bookingId]);

  useEffect(() => {
    loadInvoices();
  }, [loadInvoices]);

  const handleCreateInvoice = async () => {
    if (isOption) {
      alert('לא ניתן להפיק חשבונית לאופציה — יש להמיר לאירוע סגור תחילה.');
      return;
    }
    if (remaining <= 0) {
      alert('אין יתרה לחיוב מול האולם.');
      return;
    }

    setCreating(true);
    setError('');
    try {
      const res = await apiFetch(`${API_URL}/bookings/${bookingId}/invoice`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.message || 'שגיאה בהפקת חשבונית');
      await loadInvoices();
      onPaymentUpdated?.();
      if (json.data?.invoice?.paymentUrl) {
        window.open(json.data.invoice.paymentUrl, '_blank', 'noopener,noreferrer');
      } else {
        alert(`חשבונית נוצרה (${json.data.invoice.externalId}).`);
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'שגיאה בהפקת חשבונית';
      setError(msg);
      alert(msg);
    } finally {
      setCreating(false);
    }
  };

  return (
    <section style={{ marginTop: '16px', padding: '12px', background: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
      <h3 style={{ margin: '0 0 10px', fontSize: '1rem' }}>חשבוניות Easy Count (אולם)</h3>
      {loading ? (
        <p style={{ margin: 0, color: '#64748b' }}>טוען...</p>
      ) : (
        <>
          <p style={{ margin: '0 0 8px', fontSize: '0.9rem' }}>
            יתרה לתשלום לאולם: <strong>₪{remaining.toLocaleString()}</strong>
            {' '}(מתוך ₪{hallAmount.toLocaleString()})
          </p>
          {error && <p style={{ color: '#dc2626', margin: '0 0 8px', fontSize: '0.85rem' }}>{error}</p>}
          <button
            type="button"
            disabled={creating || isOption || remaining <= 0}
            onClick={handleCreateInvoice}
            style={{
              padding: '8px 14px',
              background: creating || isOption || remaining <= 0 ? '#94a3b8' : '#059669',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: creating || isOption || remaining <= 0 ? 'not-allowed' : 'pointer',
              marginBottom: invoices.length > 0 ? '12px' : 0,
            }}
          >
            {creating ? 'מפיקה חשבונית...' : 'הפק חשבונית Easy Count'}
          </button>
          {invoices.length > 0 && (
            <ul style={{ margin: 0, padding: 0, listStyle: 'none', fontSize: '0.85rem' }}>
              {invoices.map((inv) => (
                <li
                  key={inv.id}
                  style={{
                    padding: '8px 0',
                    borderTop: '1px solid #e2e8f0',
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: '8px',
                    alignItems: 'center',
                  }}
                >
                  <span>₪{inv.amount.toLocaleString()}</span>
                  <span style={{ color: '#64748b' }}>{inv.status}</span>
                  <span style={{ color: '#94a3b8' }}>{inv.externalId}</span>
                  {inv.paymentUrl && (
                    <a href={inv.paymentUrl} target="_blank" rel="noopener noreferrer">
                      קישור תשלום
                    </a>
                  )}
                </li>
              ))}
            </ul>
          )}
        </>
      )}
    </section>
  );
};

export default HallInvoicesPanel;

import React, { useEffect, useState } from 'react';
import { useCalendarDatesQuery } from '../../hooks/queries';
import { useNavigate } from 'react-router-dom';
import './Calendar.css';
import { EventPopup } from '../EventPopup/EventPopup';
import { getSlotColor, SLOT_COLORS, SLOT_LABELS, TIME_SLOTS, getTakenSlots, getBookableSlotsForDate, hasOptionOnDay, normalizeTimeSlot, type TimeSlot } from '../../utils/timeSlot';
import { isEventLive } from '../../utils/eventStart';
import liveStyles from '../LiveEvent/LiveEvent.module.css';
interface DayData {
  id: string | null;
  date: string;
  dayOfWeek: number;
  hebrewDate: string;
  status: string;
  reason: string | null;
  candleTime: string | null;
  lockedBy: string | null;
  bookings: any[];
  blockedSlots?: string[];
  isCurrentMonth: boolean;
}

interface CalendarProps {
  onDateSelect: (day: DayData) => void;
}

const MONTH_NAMES = ['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DOW_TO_COL: Record<number, number> = { 0:7, 1:6, 2:5, 3:4, 4:3, 5:2, 6:1 };
const COL_HEADERS = ['שבת','שישי','חמישי','רביעי','שלישי','שני','ראשון'];

/** DOM order top→bottom so flex-end stacks: evening on top, morning at bottom */
const CALENDAR_SLOT_STACK_ORDER: TimeSlot[] = ['evening', 'noon', 'morning'];

function sortBookingsForCalendarCell(bookings: any[]) {
  return [...bookings].sort((a, b) => {
    const slotA = normalizeTimeSlot(a.timeOfDay) ?? 'morning';
    const slotB = normalizeTimeSlot(b.timeOfDay) ?? 'morning';
    return CALENDAR_SLOT_STACK_ORDER.indexOf(slotA) - CALENDAR_SLOT_STACK_ORDER.indexOf(slotB);
  });
}

const formatDateLocal = (date: Date): string => {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
};

export const Calendar = ({ onDateSelect }: CalendarProps) => {const getEventTitle = (booking: any) => {
  // 1. מנקים רווחים נסתרים מסוג האירוע כדי שהקוד יזהה אותו בוודאות
  const type = (booking.eventType || '').trim(); 

  // 2. פונקציית עזר בטוחה לחילוץ שם משפחה
  const getLastName = (fullName: string) => {
    if (!fullName) return '';
    return fullName.trim().split(' ').pop() || '';
  };

  const nameA = getLastName(booking.clientAFullName);
  const nameB = getLastName(booking.clientBFullName);

  // 3. חיבור חכם של השמות - רק אם יש באמת שני צדדים שונים
  let namesDisplay = '';
  if (nameA && nameB && nameA !== nameB) {
    namesDisplay = `${nameA}-${nameB}`;
  } else {
    // אם הוזן רק צד אחד במערכת, נציג רק אותו
    namesDisplay = nameA || nameB; 
  }

  // 4. תצוגה סופית על הלוח (בלי מקף מיותר בחתונות)
  if (type === 'חתונה' || type === 'אירוסין') {
    return `${type} ${namesDisplay}`;
  }
  
  return `${type} - משפחת ${namesDisplay}`;
};
 const navigate = useNavigate();

  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<any>(null);
  const [isActionModalOpen, setIsActionModalOpen] = useState(false);
  const [selectedDateForAction, setSelectedDateForAction] = useState<string | null>(null);
  const [eventTypeFilter, setEventTypeFilter] = useState('חתונה');
  const [, setLiveTick] = useState(0);

  useEffect(() => {
    const id = window.setInterval(() => setLiveTick((t) => t + 1), 60_000);
    return () => window.clearInterval(id);
  }, []);

  const year  = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const firstDay  = new Date(year, month, 1);
  const startDate = new Date(year, month, 1 - firstDay.getDay());
  const lastDay = new Date(year, month + 1, 0);
  const endDate = new Date(year, month + 1, 0 + (6 - lastDay.getDay()));

  const startStr = formatDateLocal(startDate);
  const endStr   = formatDateLocal(endDate);

  const todayStr = formatDateLocal(new Date());

  const { data: datesData = [], isLoading: loading, isError } = useCalendarDatesQuery(startStr, endStr, eventTypeFilter);
  const datesList = Array.isArray(datesData) ? datesData : [];

  const buildGrid = () => {
    const serverMap = new Map<string, any>(datesList.map((d: any) => [d.date, d]));
    const days: (DayData & { col: number; row: number })[] = [];
    const loop = new Date(startDate);
    let row = 1;
    while (loop <= endDate) {
      const key = formatDateLocal(loop);
      const srv = serverMap.get(key);
      const dow = loop.getDay();
      days.push({
        id: srv?.id ?? null, 
        date: key, 
        dayOfWeek: dow, 
        hebrewDate: srv?.hebrewDate ?? '',
        status: srv?.status ?? 'AVAILABLE', 
        reason: srv?.reason ?? null, 
        candleTime: srv?.candleTime ?? null,
        lockedBy: srv?.lockedBy ?? null, 
        bookings: srv?.bookings ?? [],
        blockedSlots: srv?.blockedSlots ?? [],
        isCurrentMonth: loop.getMonth() === month,
        col: DOW_TO_COL[dow], row,
      });
      if (dow === 6) row++;
      loop.setDate(loop.getDate() + 1);
    }
    return days;
  };

  const grid = buildGrid();
  const weekRowCount = grid.length > 0 ? Math.max(...grid.map((d) => d.row)) : 5;

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));
  const prevYear  = () => setCurrentDate(new Date(year - 1, month, 1));
  const nextYear  = () => setCurrentDate(new Date(year + 1, month, 1));

  const handleBookEvent = () => {
    setIsActionModalOpen(false);
    const dayObj = grid.find(d => d.date === selectedDateForAction);
    if (dayObj) onDateSelect(dayObj);
  };

  const handleOverrideOptionBook = (day: DayData) => {
    if (!day.id) {
      alert('לא ניתן לשחרר את האופציה — נסי לרענן את הלוח שנה.');
      return;
    }
    const optionBooking = day.bookings?.find((b: { isOption?: boolean }) => b.isOption) || day.bookings?.[0];
    const clientName = optionBooking?.clientAFullName || 'לקוח';
    const isShabbat = new Date(`${day.date}T12:00:00`).getDay() === 6;
    const bookable = getBookableSlotsForDate(day.date, day.bookings || []);
    const shabbatNote = isShabbat && bookable.length === 0
      ? '\n\nשימי לב: בשבת ניתן לקבוע אירוע בערב בלבד.'
      : '';
    const confirmed = window.confirm(
      `קיימת אופציה עבור ${clientName} בתאריך זה.\n\nהאם את בטוחה שברצונך לשחרר את האופציה ולקבוע אירוע אחר?${shabbatNote}`,
    );
    if (!confirmed) return;

    const optionSlots = Array.from(getTakenSlots(day.bookings || []));
    navigate('/booking', {
      state: {
        date: day.date,
        hebrewDate: day.hebrewDate,
        blockedSlots: (day.blockedSlots || []) as TimeSlot[],
        takenSlots: optionSlots,
        overrideOptionDateId: day.id,
        overrideOptionSlots: optionSlots,
        overrideOptionClientName: clientName,
      },
    });
  };

  return (
    <div className="calendar-page-layout">
      <div className="calendar-container">
      
      <div className="calendar-toolbar">
        <span className="calendar-toolbar-label">בדוק זמינות עבור:</span>
        <select className="calendar-toolbar-select" value={eventTypeFilter} onChange={(e) => setEventTypeFilter(e.target.value)}>
          <option value="חתונה">חתונה</option>
          <option value="אירוע אחר">אירוע אחר</option>
        </select>
        <div className="calendar-legend">
          {TIME_SLOTS.map((slot) => (
            <span key={slot} className="calendar-legend-item">
              <span className="calendar-legend-swatch" style={{ backgroundColor: SLOT_COLORS[slot] }} />
              {SLOT_LABELS[slot]}
            </span>
          ))}
        </div>
      </div>

      <div className="calendar-header-nav">
        <div className="year-nav" style={{ direction: 'rtl' }}>
          <button className="nav-btn year-btn" onClick={nextYear} aria-label="שנה הבאה">»</button>
          <span className="year-display">{year}</span>
          <button className="nav-btn year-btn" onClick={prevYear} aria-label="שנה קודמת">«</button>
        </div>

        <div className="calendar-nav" style={{ direction: 'rtl' }}>
          <button className="nav-btn" onClick={nextMonth} aria-label="חודש הבא">›</button>
          <div className="months-bar">
            {MONTH_NAMES.map((name, i) => (
              <div key={name} className={`month-tab ${i === month ? 'active' : ''}`} onClick={() => setCurrentDate(new Date(year, i, 1))}>{name}</div>
            ))}
          </div>
          <button className="nav-btn" onClick={prevMonth} aria-label="חודש קודם">‹</button>
        </div>
      </div>

      {loading ? <div className="calendar-loading">טוען נתונים...</div> : isError ? (
        <div className="calendar-loading">שגיאה בטעינת לוח השנה — ודאי שהשרת רץ על פורט 5000</div>
      ) : (
        <div className="calendar-grid-wrapper">
          <div className="calendar-weekdays-bar">
            {COL_HEADERS.map((d) => <div key={d} className="week-day-label">{d}</div>)}
          </div>
          <div
            className="calendar-grid calendar-grid-uniform"
            style={{ ['--calendar-week-rows' as string]: weekRowCount } as React.CSSProperties}
          >
            {grid.map(day => {
              const isToday = day.date === todayStr;
              const isPast = day.date < todayStr;
              
              const dayNum = new Date(day.date + 'T12:00:00').getDate();

              const bookingCount = day.bookings?.length ?? 0;
              const cls = [
                'calendar-cell',
                `status-${day.status.toLowerCase()}`,
                !day.isCurrentMonth ? 'out-of-month' : '',
                isToday ? 'is-today' : '',
                isPast && day.isCurrentMonth ? 'is-past' : '',
                isPast && day.isCurrentMonth && bookingCount > 0 ? 'is-past-has-events' : '',
              ].filter(Boolean).join(' ');
              const isHardBlocked = day.status === 'BLOCKED' && bookingCount === 0;
              const canViewPastEvents = isPast && bookingCount > 0;
              const isCellDisabled =
                !day.isCurrentMonth || day.status === 'FORBIDDEN' || isHardBlocked || (isPast && !canViewPastEvents);
              const ariaLabel = day.isCurrentMonth
                ? `${dayNum} ${day.hebrewDate || ''}, ${bookingCount} אירועים${day.reason ? `, ${day.reason}` : ''}${canViewPastEvents ? ', לחצי לצפייה בפרטים' : ''}`
                : `${dayNum}`;

              return (
                <button
                  type="button"
                  key={day.date}
                  className={cls}
                  style={{ gridColumn: day.col, gridRow: day.row }}
                  aria-label={ariaLabel}
                  disabled={isCellDisabled}
                  onClick={() => {
                  if (!day.isCurrentMonth || day.status === 'FORBIDDEN' || isHardBlocked) return;
                  if (isPast) {
                    if (bookingCount > 0) setSelectedDay(day);
                    return;
                  }

                  if (day.bookings.length > 0) { setSelectedDay(day); return; }
                  setSelectedDateForAction(day.date); setIsActionModalOpen(true);
                }}>
                  <div className="cell-header-row">
                      <span className="gregorian-num">
                        {dayNum}
                        {isToday && <span className="today-badge">היום</span>}
                      </span>
                      {day.isCurrentMonth && day.candleTime && <span className="candle-time">{day.candleTime}</span>}
                      <span className="hebrew-text">{day.isCurrentMonth ? day.hebrewDate : ''}</span>
                  </div>
                  
                  <div className="cell-status-text">{day.isCurrentMonth ? (day.reason || '') : ''}</div>
                  <div className="cell-events-container">
                    {sortBookingsForCalendarCell(day.bookings).map((b: any, idx: number) => {
                      const baseColor = getSlotColor(b.timeOfDay);
                      const isOptionBooking = b.isOption === true;
                      const isLive =
                        !isOptionBooking
                        && day.status === 'BOOKED'
                        && isEventLive(day.date, b, b.eventForm);
                      
                      // העיצוב המתוקן שיוצר קונטרסט ברור:
                      const eventStyle = isOptionBooking
                        ? { 
                            backgroundColor: `${baseColor}18`,
                            border: `1.5px dashed ${baseColor}`,
                            color: baseColor,
                            fontWeight: '700'
                          }
                        : { 
                            backgroundColor: baseColor,
                            border: `1.5px solid ${baseColor}`,
                            color: '#FFFFFF',
                            fontWeight: '700',
                            boxShadow: '0 1px 3px rgba(0,0,0,0.12)'
                          };

                      return (
                        <div 
                          key={idx} 
                          className="small-event-pill"
                          style={eventStyle}
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedDay(day);
                          }}
                        >
                          {isLive && <span className={liveStyles.liveBadge}>חי</span>}
                          {getEventTitle(b)}
                        </div>
                      );
                    })}
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}
      {selectedDay && (
        <EventPopup
          day={selectedDay}
          onClose={() => setSelectedDay(null)}
          onAddEvent={() => {
            const dayToBook = selectedDay;
            setSelectedDay(null);
            onDateSelect(dayToBook);
          }}
          onAddOption={() => {
            const dayToOption = selectedDay;
            setSelectedDay(null);
            navigate('/option', {
              state: {
                selectedDates: [{ date: dayToOption.date, hebrewDate: dayToOption.hebrewDate || '' }],
                takenSlots: Array.from(getTakenSlots(dayToOption.bookings || [])),
                blockedSlots: (dayToOption.blockedSlots || []) as TimeSlot[],
              },
            });
          }}
          onOverrideOptionBook={
            hasOptionOnDay(selectedDay)
              ? () => handleOverrideOptionBook(selectedDay)
              : undefined
          }
        />
      )}

      {isActionModalOpen && (
        <div className="side-panel-overlay" onClick={() => setIsActionModalOpen(false)}>
          <div className="side-panel" onClick={e => e.stopPropagation()}>
            <div className="side-panel-header">
              <span>תאריך: {selectedDateForAction?.split('-').reverse().join('-')}</span>
              <button className="side-panel-close" onClick={() => setIsActionModalOpen(false)}>✕</button>
            </div>
            <div className="side-panel-body">
              <button className="book-btn" onClick={handleBookEvent}>סגירת אירוע</button>
              <button
                className="option-btn"
                onClick={() => {
                  if (!selectedDateForAction) return;
                  const dayData = datesList.find((d: any) => d.date === selectedDateForAction);
                  setIsActionModalOpen(false);
                  navigate('/option', {
                    state: {
                      selectedDates: [{
                        date: selectedDateForAction,
                        hebrewDate: dayData?.hebrewDate || '',
                      }],
                    },
                  });
                }}
              >
                פתיחת אופציה
              </button>
            </div>
          </div>
        </div>
      )}
      </div>
    </div>
  );
};

import { useMemo } from 'react';
import { Link } from 'react-router-dom';
import {
  useBookingsQuery,
  useCalendarDatesQuery,
  useFeedbackStatsQuery,
} from '../../hooks/queries';
import {
  StatCard,
  Card,
  CardHeader,
  CardBody,
  Button,
  Badge,
  SkeletonGroup,
} from '../ui';
import { UpcomingEventsPanel } from './UpcomingEventsPanel';
import { MiniCalendar } from './MiniCalendar';
import styles from './Dashboard.module.css';

const startOfDay = (d: Date) => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const getEventDay = (b: any) =>
  b.eventDate?.date ? startOfDay(new Date(b.eventDate.date)) : null;

const Dashboard = () => {
  const now = new Date();
  const year = String(now.getFullYear());
  const month = String(now.getMonth() + 1);

  const monthStart = `${year}-${month.padStart(2, '0')}-01`;
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0)
    .toISOString()
    .slice(0, 10);

  const { data: bookedData, isLoading: bookedLoading } = useBookingsQuery({
    status: 'BOOKED',
    page: 1,
    limit: 500,
  });

  const { data: optionsData, isLoading: optionsLoading } = useBookingsQuery({
    status: 'OPTION',
    page: 1,
    limit: 500,
  });

  const { data: calendarData, isLoading: calendarLoading } = useCalendarDatesQuery(
    monthStart,
    monthEnd,
    '',
  );

  const { data: feedbackStats, isLoading: feedbackLoading } = useFeedbackStatsQuery(
    year,
    month,
  );

  const upcomingCount = useMemo(() => {
    const today = startOfDay(new Date());
    const in30 = new Date(today);
    in30.setDate(in30.getDate() + 30);
    return (bookedData?.data ?? []).filter((b: any) => {
      if (b.isOption) return false;
      const day = getEventDay(b);
      return day !== null && day >= today && day <= in30;
    }).length;
  }, [bookedData]);

  const openOptionsCount = useMemo(() => {
    const today = startOfDay(new Date());
    return (optionsData?.data ?? []).filter((b: any) => {
      if (b.isOption === false) return false;
      const day = getEventDay(b);
      return day !== null && day >= today;
    }).length;
  }, [optionsData]);

  const eventsThisMonth = useMemo(() => {
    if (!Array.isArray(calendarData)) return 0;
    return calendarData.reduce((sum: number, day: any) => {
      const bookings = day.bookings?.filter((b: any) => !b.isOption) ?? [];
      return sum + bookings.length;
    }, 0);
  }, [calendarData]);

  const avgScore = feedbackStats?.averages?.combined;
  const avgScoreDisplay =
    avgScore != null ? avgScore.toFixed(1) : '—';

  const recentActivity = useMemo(() => {
    const booked = (bookedData?.data ?? []).filter((b: any) => !b.isOption);
    const options = (optionsData?.data ?? []).filter((b: any) => b.isOption !== false);
    const combined = [
      ...booked.map((b: any) => ({ ...b, _type: 'booked' as const })),
      ...options.map((b: any) => ({ ...b, _type: 'option' as const })),
    ];
    return combined
      .filter((b) => getEventDay(b))
      .sort((a, b) => getEventDay(b)!.getTime() - getEventDay(a)!.getTime())
      .slice(0, 6);
  }, [bookedData, optionsData]);

  const metricsLoading = bookedLoading || optionsLoading || calendarLoading || feedbackLoading;

  return (
    <div className={styles.dashboard}>
      <header className={styles.pageHeader}>
        <div>
          <h1 className={styles.title}>לוח בקרה</h1>
          <p className={styles.subtitle}>סקירה כללית של האירועים וההזמנות במתחם</p>
        </div>
        <Link to="/calendar">
          <Button variant="primary">לוח שנה מלא</Button>
        </Link>
      </header>

      <section className={styles.metrics} aria-label="מדדי ביצוע">
        <StatCard
          label="אירועים קרובים (30 יום)"
          value={upcomingCount}
          icon="calendar"
          loading={metricsLoading}
        />
        <StatCard
          label="אופציות פתוחות"
          value={openOptionsCount}
          icon="clipboard"
          loading={metricsLoading}
        />
        <StatCard
          label="אירועים החודש"
          value={eventsThisMonth}
          icon="event"
          loading={metricsLoading}
        />
        <StatCard
          label="ציון משוב ממוצע"
          value={avgScoreDisplay}
          icon="star"
          trend={avgScore != null ? 'מתוך 5' : undefined}
          loading={metricsLoading}
        />
      </section>

      <section className={styles.upcoming}>
        <UpcomingEventsPanel />
      </section>

      <section className={styles.miniCal}>
        <Card>
          <CardHeader title="לוח שנה — החודש">
            <Link to="/calendar">
              <Button variant="secondary" size="sm">
                פתיחה
              </Button>
            </Link>
          </CardHeader>
          <CardBody>
            {calendarLoading ? (
              <SkeletonGroup rows={4} />
            ) : (
              <MiniCalendar days={calendarData ?? []} />
            )}
          </CardBody>
        </Card>
      </section>

      <section className={styles.activity}>
        <Card compact>
          <CardHeader title="פעילות אחרונה" />
          <CardBody>
            {metricsLoading ? (
              <SkeletonGroup rows={4} />
            ) : recentActivity.length === 0 ? (
              <p className={styles.emptyActivity}>אין פעילות להצגה</p>
            ) : (
              <ul className={styles.activityList}>
                {recentActivity.map((b: any) => (
                  <li key={b.id} className={styles.activityItem}>
                    <div className={styles.activityInfo}>
                      <span className={styles.activityName}>{b.clientAFullName}</span>
                      <span className={styles.activityMeta}>
                        {getEventDay(b)?.toLocaleDateString('he-IL')} · {b.eventType}
                      </span>
                    </div>
                    <Badge variant={b._type === 'option' ? 'option' : 'confirmed'}>
                      {b._type === 'option' ? 'אופציה' : 'מאושר'}
                    </Badge>
                  </li>
                ))}
              </ul>
            )}
          </CardBody>
        </Card>
      </section>
    </div>
  );
};

export default Dashboard;

import { useMemo } from 'react';
import { Link } from 'react-router-dom';
import styles from './MiniCalendar.module.css';

const HEBREW_DAYS = ['א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ש'];
const HEBREW_MONTHS = [
  'ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני',
  'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר',
];

interface MiniCalendarProps {
  days: any[];
}

export function MiniCalendar({ days }: MiniCalendarProps) {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();

  const dayMap = useMemo(() => {
    const map = new Map<string, any>();
    for (const d of days) {
      if (d.date) map.set(d.date.slice(0, 10), d);
    }
    return map;
  }, [days]);

  const firstDay = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const startOffset = firstDay.getDay();

  const cells: (number | null)[] = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const todayStr = now.toISOString().slice(0, 10);

  return (
    <div className={styles.wrap}>
      <p className={styles.monthLabel}>
        {HEBREW_MONTHS[month]} {year}
      </p>
      <div className={styles.grid} role="grid" aria-label={`לוח שנה ${HEBREW_MONTHS[month]} ${year}`}>
        {HEBREW_DAYS.map((d) => (
          <div key={d} className={styles.dayHeader} role="columnheader">
            {d}
          </div>
        ))}
        {cells.map((day, i) => {
          if (day === null) {
            return <div key={`empty-${i}`} className={styles.emptyCell} />;
          }
          const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const dayData = dayMap.get(dateStr);
          const bookingCount = dayData?.bookings?.filter((b: any) => !b.isOption)?.length ?? 0;
          const isToday = dateStr === todayStr;

          return (
            <Link
              key={dateStr}
              to="/calendar"
              className={`${styles.cell} ${isToday ? styles.today : ''} ${bookingCount > 0 ? styles.hasBookings : ''}`}
              aria-label={`${day} ${HEBREW_MONTHS[month]}, ${bookingCount} אירועים`}
            >
              <span className={styles.dayNum}>{day}</span>
              {bookingCount > 0 && (
                <span className={styles.dot} aria-hidden="true" />
              )}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

import { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { useBookingsQuery } from '../../hooks/queries';
import {
  SectionHeader,
  DataTable,
  EventCard,
  Button,
  Badge,
  SkeletonGroup,
  type DataTableColumn,
  type EventCardData,
} from '../ui';
import styles from './UpcomingEventsPanel.module.css';

const startOfDay = (d: Date) => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const getEventDay = (b: any) =>
  b.eventDate?.date ? startOfDay(new Date(b.eventDate.date)) : null;

const dateStr = (b: any) =>
  b.eventDate?.date ? new Date(b.eventDate.date).toLocaleDateString('he-IL') : '—';

const toEventCard = (b: any): EventCardData => ({
  id: b.id,
  date: dateStr(b),
  code: b.eventCode,
  clientName: b.clientAFullName,
  clientNameB: b.clientBFullName,
  eventType: b.eventType,
  timeOfDay: b.timeOfDay,
  guestCount:
    b.eventType === 'השכרת אולם בלי אוכל'
      ? 'השכרת אולם (ללא מנות)'
      : b.guestCount,
  status: 'confirmed',
  statusLabel: 'מאושר',
});

export function UpcomingEventsPanel() {
  const { data, isLoading } = useBookingsQuery({
    status: 'BOOKED',
    page: 1,
    limit: 500,
  });

  const upcoming = useMemo(() => {
    const today = startOfDay(new Date());
    return (data?.data ?? [])
      .filter((b: any) => !b.isOption)
      .filter((b: any) => {
        const day = getEventDay(b);
        return day !== null && day >= today;
      })
      .sort((a: any, b: any) => getEventDay(a)!.getTime() - getEventDay(b)!.getTime())
      .slice(0, 5);
  }, [data]);

  const columns: DataTableColumn<any>[] = [
    { key: 'date', header: 'תאריך', render: (b) => dateStr(b) },
    { key: 'code', header: 'קוד', render: (b) => b.eventCode ? `#${b.eventCode}` : '—' },
    { key: 'client', header: 'לקוח', render: (b) => b.clientAFullName },
    { key: 'type', header: 'סוג', render: (b) => b.eventType },
    {
      key: 'guests',
      header: 'מוזמנים',
      render: (b) =>
        b.eventType === 'השכרת אולם בלי אוכל' ? '—' : b.guestCount ?? '—',
    },
    {
      key: 'status',
      header: 'סטטוס',
      render: () => <Badge variant="confirmed">מאושר</Badge>,
    },
  ];

  return (
    <div className={styles.panel}>
      <SectionHeader
        title="אירועים קרובים"
        count={upcoming.length}
        action={
          <Link to="/bookings-manager">
            <Button variant="secondary" size="sm">
              הצג הכל
            </Button>
          </Link>
        }
      />

      {isLoading ? (
        <SkeletonGroup rows={3} />
      ) : upcoming.length === 0 ? (
        <p className={styles.empty}>אין אירועים קרובים</p>
      ) : (
        <>
          <div className={styles.tableWrap}>
            <DataTable
              caption="אירועים קרובים"
              columns={columns}
              data={upcoming}
              rowKey={(b: any) => b.id}
            />
          </div>
          <div className={styles.cardsWrap}>
            {upcoming.map((b: any) => (
              <EventCard key={b.id} event={toEventCard(b)} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

