import React, { useState, useRef, useCallback, useMemo, useEffect } from 'react';
import floorPlanImg from '../../assets/floor-plan.png';
import {
  DEFAULT_TABLE_LAYOUT,
  DEFAULT_TABLE_SIZE,
  SECTION_BOUNDS,
  SEATS_PER_TABLE,
  buildLayoutForGuestCount,
  clampToSection,
  createTableInSection,
  getNextTableId,
} from '../../constants/defaultTableLayout';
import type { TableData, TableSection } from '../../constants/defaultTableLayout';
import { exportFloorPlanAsImage, renderFloorPlanToDataUrl } from '../../utils/exportFloorPlan';
import { getAuthUser } from '../../services/api';
import {
  clearFloorPlanDraft,
  loadFloorPlanDraft,
  saveFloorPlanDraft,
} from '../../utils/floorPlanDraft';
import './FloorPlanBuilder.css';

export type { TableData };

function clampPct(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

interface LayoutConfig {
  guestCount: number;
  seatingType?: string;
  menPercent?: number;
  womenPercent?: number;
  includeHonorTables?: boolean;
}

function resolveInitialTables(
  initialTables: TableData[] | undefined,
  layoutConfig: LayoutConfig,
): TableData[] {
  if (initialTables && initialTables.length > 0) {
    return initialTables.map(clampToSection);
  }
  if (layoutConfig.guestCount > 0) {
    return buildLayoutForGuestCount({
      guestCount: layoutConfig.guestCount,
      seatingType: layoutConfig.seatingType,
      menPercent: layoutConfig.menPercent,
      womenPercent: layoutConfig.womenPercent,
      includeHonorTables: layoutConfig.includeHonorTables,
    });
  }
  return DEFAULT_TABLE_LAYOUT.map(t => ({ ...t }));
}

interface TableItemProps {
  table: TableData;
  isSelected: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
  onSelect: (id: number) => void;
  onMove: (id: number, x: number, y: number) => void;
}

const TableItem: React.FC<TableItemProps> = ({
  table,
  isSelected,
  containerRef,
  onSelect,
  onMove,
}) => {
  const tableW = DEFAULT_TABLE_SIZE;
  const tableH = DEFAULT_TABLE_SIZE;
  const bounds = SECTION_BOUNDS[table.section];

  const [dragOffset, setDragOffset] = useState<{ x: number; y: number } | null>(null);
  const dragRef = useRef<{ startX: number; startY: number } | null>(null);

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    e.preventDefault();
    e.stopPropagation();
    onSelect(table.id);

    const el = e.currentTarget;
    el.setPointerCapture(e.pointerId);
    dragRef.current = { startX: e.clientX, startY: e.clientY };
    setDragOffset({ x: 0, y: 0 });
    el.classList.add('table-dragging');
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragRef.current) return;
    e.preventDefault();
    setDragOffset({
      x: e.clientX - dragRef.current.startX,
      y: e.clientY - dragRef.current.startY,
    });
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragRef.current || !dragOffset) return;

    const el = e.currentTarget;
    if (el.hasPointerCapture(e.pointerId)) {
      el.releasePointerCapture(e.pointerId);
    }
    el.classList.remove('table-dragging');

    const container = containerRef.current;
    if (container) {
      const rect = container.getBoundingClientRect();
      const dxPct = (dragOffset.x / rect.width) * 100;
      const dyPct = (dragOffset.y / rect.height) * 100;
      const newX = clampPct(table.x + dxPct, bounds.minX, bounds.maxX - tableW);
      const newY = clampPct(table.y + dyPct, bounds.minY, bounds.maxY - tableH);
      onMove(table.id, newX, newY);
    }

    dragRef.current = null;
    setDragOffset(null);
  };

  const sectionClass = table.section === 'women' ? 'table-women' : 'table-men';
  const honorClass = table.isHonor ? 'table-honor' : '';

  return (
    <div
      className={`table-box ${sectionClass} ${honorClass} ${isSelected ? 'table-selected' : ''}`}
      style={{
        left: `${table.x}%`,
        top: `${table.y}%`,
        width: `${tableW}%`,
        height: `${tableH}%`,
        transform: dragOffset ? `translate(${dragOffset.x}px, ${dragOffset.y}px)` : undefined,
      }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
    >
      {table.isHonor ? 'R' : table.id}
    </div>
  );
};

interface Props {
  initialTables?: TableData[];
  guestCount?: number;
  seatingType?: string;
  menPercent?: number;
  womenPercent?: number;
  includeHonorTables?: boolean;
  onSave: (tables: TableData[], imageDataUrl: string) => void;
  onClose?: () => void;
  downloadFileName?: string;
  draftEventId?: string;
}

export const FloorPlanBuilder: React.FC<Props> = ({
  initialTables,
  guestCount = 0,
  seatingType = 'separate',
  menPercent,
  womenPercent,
  includeHonorTables = true,
  onSave,
  onClose,
  downloadFileName,
  draftEventId,
}) => {
  const layoutConfig = useMemo<LayoutConfig>(() => ({
    guestCount,
    seatingType,
    menPercent,
    womenPercent,
    includeHonorTables,
  }), [guestCount, seatingType, menPercent, womenPercent, includeHonorTables]);

  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [draftLoaded, setDraftLoaded] = useState(false);

  const [tables, setTables] = useState<TableData[]>(() => resolveInitialTables(initialTables, layoutConfig));
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [layoutKey, setLayoutKey] = useState(0);
  const [exporting, setExporting] = useState(false);
  const [saving, setSaving] = useState(false);
  const canvasRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    getAuthUser().then((user) => {
      if (user?.email) setUserEmail(user.email);
    });
  }, []);

  useEffect(() => {
    if (!draftEventId || !userEmail || draftLoaded) return;
    const draft = loadFloorPlanDraft(draftEventId, userEmail);
    if (draft && draft.length > 0) {
      setTables(draft.map(clampToSection));
      setLayoutKey((k) => k + 1);
    }
    setDraftLoaded(true);
  }, [draftEventId, userEmail, draftLoaded]);

  useEffect(() => {
    if (!draftEventId || !userEmail || !draftLoaded) return;
    const timer = setTimeout(() => {
      saveFloorPlanDraft(draftEventId, userEmail, tables);
    }, 500);
    return () => clearTimeout(timer);
  }, [draftEventId, userEmail, draftLoaded, tables]);

  const handleMove = useCallback((id: number, x: number, y: number) => {
    setTables(prev =>
      prev.map(t => (t.id === id ? clampToSection({ ...t, x, y }) : t))
    );
  }, []);

  const handleAddTable = (section: TableSection) => {
    const newId = getNextTableId(tables);
    const newTable = createTableInSection(section, newId);
    setTables(prev => [...prev, newTable]);
    setSelectedId(newId);
    setLayoutKey(k => k + 1);
  };

  const handleDeleteSelected = () => {
    if (selectedId === null) return;
    const table = tables.find(t => t.id === selectedId);
    if (!table) return;
    if (table.isHonor && DEFAULT_TABLE_LAYOUT.some(d => d.id === table.id && d.isHonor)) {
      alert('לא ניתן למחוק שולחן כבוד מברירת המחדל');
      return;
    }
    setTables(prev => prev.filter(t => t.id !== selectedId));
    setSelectedId(null);
    setLayoutKey(k => k + 1);
  };

  const handleRebuildFromGuests = () => {
    if (guestCount <= 0) {
      alert('יש להזין כמות מוזמנים סופית בטופס');
      return;
    }
    const tableCount = Math.ceil(guestCount / SEATS_PER_TABLE);
    if (!confirm(`ליצור סידור מחדש ל-${guestCount} מוזמנים (${tableCount} שולחנות)?`)) {
      return;
    }
    setTables(buildLayoutForGuestCount({
      guestCount,
      seatingType,
      menPercent,
      womenPercent,
      includeHonorTables,
    }));
    setSelectedId(null);
    setLayoutKey(k => k + 1);
  };

  const handleReset = () => {
    if (confirm('לאפס לסידור ברירת המחדל?')) {
      setTables(DEFAULT_TABLE_LAYOUT.map(t => ({ ...t })));
      setSelectedId(null);
      setLayoutKey(k => k + 1);
    }
  };

  const handleDownload = async () => {
    setExporting(true);
    try {
      await exportFloorPlanAsImage(
        tables,
        floorPlanImg,
        downloadFileName ?? 'sidur-shulchanot.png'
      );
    } catch {
      alert('שגיאה ביצירת התמונה');
    } finally {
      setExporting(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const imageDataUrl = await renderFloorPlanToDataUrl(tables, floorPlanImg);
      if (draftEventId) clearFloorPlanDraft(draftEventId);
      onSave(tables, imageDataUrl);
    } catch {
      alert('שגיאה בשמירת הסקיצה');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="floor-plan-container">
      <div className="floor-plan-toolbar">
        <div className="toolbar-actions">
          {guestCount > 0 && (
            <button type="button" className="btn-rebuild" onClick={handleRebuildFromGuests}>
              רענן לפי מוזמנים
            </button>
          )}
          <button type="button" className="btn-add-women" onClick={() => handleAddTable('women')}>
            + שולחן נשים
          </button>
          <button type="button" className="btn-add-men" onClick={() => handleAddTable('men')}>
            + שולחן גברים
          </button>
          <button
            type="button"
            className="btn-delete"
            onClick={handleDeleteSelected}
            disabled={selectedId === null}
          >
            מחק שולחן נבחר
          </button>
          <button type="button" className="btn-reset" onClick={handleReset}>
            איפוס לברירת מחדל
          </button>
          <button
            type="button"
            className="btn-download"
            onClick={handleDownload}
            disabled={exporting}
          >
            {exporting ? 'מוריד...' : '⬇ הורדת תמונה'}
          </button>
        </div>
        <div className="toolbar-save">
          <button type="button" className="btn-save" onClick={handleSave} disabled={saving}>
            {saving ? 'שומר...' : 'שמור סידור'}
          </button>
          {onClose && (
            <button type="button" className="btn-close" onClick={onClose}>
              סגור
            </button>
          )}
        </div>
      </div>

      <div className="floor-plan-viewport">
        <div className="hall-canvas" ref={canvasRef}>
          <img
            src={floorPlanImg}
            alt="מפת אולם"
            className="hall-background"
            draggable={false}
          />
          <div className="tables-layer" key={layoutKey}>
            {tables.map(table => (
              <TableItem
                key={table.id}
                table={table}
                containerRef={canvasRef}
                isSelected={selectedId === table.id}
                onSelect={setSelectedId}
                onMove={handleMove}
              />
            ))}
          </div>
        </div>
      </div>

      <div className="floor-plan-legend">
        <span className="legend-item"><span className="legend-dot women" /> נשים</span>
        <span className="legend-item"><span className="legend-dot men" /> גברים</span>
        <span className="legend-item"><span className="legend-dot honor" /> שולחן כבוד (R)</span>
        <span className="legend-hint">גררי שולחן עם העכבר / האצבע · לחיצה לבחירה</span>
      </div>
    </div>
  );
};

export default FloorPlanBuilder;

import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { API_URL } from '../../config/api';
import { secureFetch } from '../../services/api';
import styles from './GreetingBlast.module.css';

type GreetingStatus = 'PENDING' | 'PROCESSING' | 'SENT' | 'FAILED' | 'CANCELLED';

type ScheduledGreetingItem = {
  id: string;
  subject: string;
  message: string;
  scheduledAt: string;
  attachmentName: string | null;
  status: GreetingStatus;
  sentAt: string | null;
  sendStats: {
    emailSent?: number;
    whatsappSent?: number;
  } | null;
  errorMessage: string | null;
  createdBy: string | null;
  createdAt: string;
};

type StatusFilter = 'ALL' | 'PENDING' | 'SENT' | 'FAILED';

const STATUS_LABELS: Record<GreetingStatus, string> = {
  PENDING: 'ממתין',
  PROCESSING: 'נשלח עכשיו',
  SENT: 'נשלח',
  FAILED: 'נכשל',
  CANCELLED: 'בוטל',
};

const formatDateTime = (iso: string) =>
  new Date(iso).toLocaleString('he-IL', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });

const GreetingBlast = () => {
  const navigate = useNavigate();
  const [subject, setSubject] = useState('');
  const [message, setMessage] = useState('');
  const [scheduledDate, setScheduledDate] = useState('');
  const [scheduledTime, setScheduledTime] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sent, setSent] = useState(false);
  const [resultMessage, setResultMessage] = useState('');
  const [scheduledItems, setScheduledItems] = useState<ScheduledGreetingItem[]>([]);
  const [listLoading, setListLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');
  const [cancellingId, setCancellingId] = useState<string | null>(null);

  const loadScheduledGreetings = useCallback(async (silent = false) => {
    if (!silent) setListLoading(true);
    try {
      const res = await secureFetch(`${API_URL}/bookings/scheduled-greetings`, {
        credentials: 'include',
      });
      const data = await res.json();
      if (data.success) {
        setScheduledItems(data.items || []);
      }
    } catch {
      // silent — list is secondary
    } finally {
      if (!silent) setListLoading(false);
    }
  }, []);

  useEffect(() => {
    loadScheduledGreetings();
  }, [loadScheduledGreetings]);

  const hasActiveScheduled = scheduledItems.some(
    (item) => item.status === 'PENDING' || item.status === 'PROCESSING',
  );

  useEffect(() => {
    if (!hasActiveScheduled) return undefined;

    const intervalId = window.setInterval(() => {
      loadScheduledGreetings(true);
    }, 30_000);

    return () => window.clearInterval(intervalId);
  }, [hasActiveScheduled, loadScheduledGreetings]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const formData = new FormData();
      formData.append('subject', subject);
      formData.append('message', message);
      formData.append('scheduledDate', scheduledDate);
      formData.append('scheduledTime', scheduledTime);
      if (file) formData.append('attachment', file);

      const res = await secureFetch(`${API_URL}/bookings/send-greeting`, {
        method: 'POST',
        credentials: 'include',
        body: formData,
      });

      const result = await res.json();
      if (result.success) {
        setResultMessage(result.message || 'הברכה נשלחה לכל הלקוחות');
        setSent(true);
        await loadScheduledGreetings();
      } else {
        const detail = result.skippedReasons?.length
          ? `${result.message}\n\n${result.skippedReasons.join('\n')}`
          : result.message || 'שגיאה בשליחה';
        alert(detail);
      }
    } catch {
      alert('שגיאת תקשורת עם השרת');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCancel = async (id: string) => {
    if (!window.confirm('לבטל את הברכה המתוזמנת?')) return;
    setCancellingId(id);
    try {
      const res = await secureFetch(`${API_URL}/bookings/scheduled-greetings/${id}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      const data = await res.json();
      if (data.success) {
        await loadScheduledGreetings();
      } else {
        alert(data.message || 'לא ניתן לבטל');
      }
    } catch {
      alert('שגיאת תקשורת עם השרת');
    } finally {
      setCancellingId(null);
    }
  };

  const resetForm = () => {
    setSent(false);
    setSubject('');
    setMessage('');
    setScheduledDate('');
    setScheduledTime('');
    setFile(null);
    setResultMessage('');
  };

  const filteredItems = scheduledItems.filter((item) => {
    if (statusFilter === 'ALL') return true;
    if (statusFilter === 'PENDING') return item.status === 'PENDING' || item.status === 'PROCESSING';
    return item.status === statusFilter;
  });

  const renderStats = (item: ScheduledGreetingItem) => {
    if (item.status !== 'SENT' || !item.sendStats) return null;
    const parts: string[] = [];
    if (item.sendStats.emailSent) parts.push(`${item.sendStats.emailSent} מיילים`);
    if (item.sendStats.whatsappSent) parts.push(`${item.sendStats.whatsappSent} וואטסאפ`);
    return parts.length ? parts.join(' · ') : null;
  };

  if (sent) {
    return (
      <div className={styles.container}>
        <div className={styles.successBox}>
          <div className={styles.successIcon}>✅</div>
          <h2>הברכה תישלח בהצלחה!</h2>
          <p>
            {scheduledDate && scheduledTime
              ? `מתוזמנת לשליחה בתאריך ${scheduledDate.split('-').reverse().join('/')} בשעה ${scheduledTime}. השליחה תתבצע אוטומטית — גם אם השרת יופעל מחדש.`
              : resultMessage || 'הברכה נשלחה לכל הלקוחות'}
          </p>
          <div className={styles.successActions}>
            {scheduledDate && scheduledTime && (
              <button type="button" className={styles.secondaryBtn} onClick={resetForm}>
                חזרה לרשימה
              </button>
            )}
            <button type="button" className={styles.backBtn} onClick={() => navigate('/calendar')}>
              חזרה ללוח
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.container}>
      <div className={styles.layout}>
        <div className={styles.card}>
          <div className={styles.header}>
            <h2 className={styles.title}>שליחת ברכה ללקוחות 💌</h2>
          </div>

          <form onSubmit={handleSubmit} className={styles.form}>
            <div className={styles.section}>
              <h3 className={styles.sectionTitle}>תזמון שליחה</h3>
              <div className={styles.row}>
                <div className={styles.inputGroup}>
                  <label>תאריך שליחה</label>
                  <input
                    type="date"
                    className={styles.input}
                    value={scheduledDate}
                    onChange={(e) => setScheduledDate(e.target.value)}
                  />
                </div>
                <div className={styles.inputGroup}>
                  <label>שעת שליחה</label>
                  <input
                    type="time"
                    className={styles.input}
                    value={scheduledTime}
                    onChange={(e) => setScheduledTime(e.target.value)}
                  />
                </div>
              </div>
              <p className={styles.hint}>
                {scheduledDate && scheduledTime
                  ? `📅 תישלח בתאריך ${scheduledDate.split('-').reverse().join('/')} בשעה ${scheduledTime}`
                  : 'אם לא תבחרי תאריך ושעה - הברכה תישלח מיד'}
              </p>
            </div>

            <div className={styles.section}>
              <h3 className={styles.sectionTitle}>תוכן הברכה</h3>
              <div className={styles.inputGroup}>
                <label>נושא המייל *</label>
                <input
                  type="text"
                  required
                  className={styles.input}
                  value={subject}
                  onChange={(e) => setSubject(e.target.value)}
                  placeholder="לדוגמה: ברכות לחג הפסח מגן אירועים מייפל 🌸"
                />
              </div>
              <div className={styles.inputGroup}>
                <label>תוכן הברכה *</label>
                <textarea
                  required
                  className={styles.textarea}
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  rows={6}
                  placeholder="כתבי כאן את תוכן הברכה שתישלח לכל הלקוחות..."
                />
              </div>
            </div>

            <div className={styles.section}>
              <h3 className={styles.sectionTitle}>קובץ מצורף (אופציונלי)</h3>
              <div className={styles.fileArea}>
                <input
                  type="file"
                  id="fileInput"
                  accept="image/*,.pdf,.doc,.docx"
                  style={{ display: 'none' }}
                  onChange={(e) => setFile(e.target.files?.[0] || null)}
                />
                <label htmlFor="fileInput" className={styles.fileLabel}>
