import React, { useEffect, useRef, useState } from 'react';
import SignatureCanvas from 'react-signature-canvas';
import styles from './LiveEvent.module.css';

export interface ReserveTableRow {
  number: number;
  value: string;
}

export interface CheckInFormData {
  familiesLabel: string;
  orderedPortions: number | '';
  entertainerPortions: number | '';
  reservePortions: number | '';
  reserveTables: ReserveTableRow[];
  specialAdditionLine1: string;
  specialAdditionLine2: string;
  customerSignature: string | null;
}

interface EventCheckInBoardProps {
  dateDisplay: string;
  initialData: CheckInFormData;
  readOnly?: boolean;
  onSave: (data: CheckInFormData) => Promise<void>;
  onCancel: () => void;
}

const EventCheckInBoard: React.FC<EventCheckInBoardProps> = ({
  dateDisplay,
  initialData,
  readOnly = false,
  onSave,
  onCancel,
}) => {
  const [form, setForm] = useState<CheckInFormData>(initialData);
  const [saving, setSaving] = useState(false);
  const sigCanvas = useRef<SignatureCanvas>(null);
  const sigLoaded = useRef(false);

  useEffect(() => {
    setForm(initialData);
    sigLoaded.current = false;
  }, [initialData]);

  useEffect(() => {
    if (initialData.customerSignature && sigCanvas.current && !sigLoaded.current) {
      sigCanvas.current.fromDataURL(initialData.customerSignature);
      sigLoaded.current = true;
    }
  }, [initialData.customerSignature]);

  const handleReserveChange = (num: number, value: string) => {
    setForm((prev) => ({
      ...prev,
      reserveTables: prev.reserveTables.map((row) =>
        row.number === num ? { ...row, value } : row
      ),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (readOnly) return;

    const signature = sigCanvas.current?.isEmpty()
      ? form.customerSignature
      : sigCanvas.current?.getCanvas().toDataURL('image/png') ?? null;

    if (!signature?.trim()) {
      alert('חובה לחתום לפני שמירת הטופס');
      return;
    }

    setSaving(true);
    try {
      await onSave({ ...form, customerSignature: signature });
    } finally {
      setSaving(false);
    }
  };

  return (
    <form className={styles.checkInBoard} onSubmit={handleSubmit}>
      <p className={styles.checkInBsd}>בס&quot;ד</p>

      <div className={styles.checkInHeader}>
        <img src="/logo.png" alt="מייפל" className={styles.checkInLogo} />
        <p className={styles.checkInBrand}>מייפל</p>
        <p className={styles.checkInSubtitle}>גן אירועים בעיר</p>
      </div>

      <div className={styles.checkInInlineRow}>
        <span className={styles.checkInInlineLabel}>משפחות:</span>
        <input
          type="text"
          className={styles.checkInInlineInput}
          value={form.familiesLabel}
          readOnly={readOnly}
          onChange={(e) => setForm((p) => ({ ...p, familiesLabel: e.target.value }))}
        />
      </div>

      <div className={styles.checkInInlineRow}>
        <span className={styles.checkInInlineLabel}>תאריך:</span>
        <input
          type="text"
          className={styles.checkInInlineInput}
          value={dateDisplay}
          readOnly
        />
      </div>

      <p className={styles.checkInConfirmText}>
        הריני לאשר בזאת שקיבלתי את האולם לפי שביעות רצוני,
      </p>

      <div className={styles.checkInInlineRow}>
        <span className={styles.checkInInlineLabel}>מספר המנות שהזמנתי:</span>
        <input
          type="number"
          min="0"
          className={styles.checkInInlineInput}
          value={form.orderedPortions}
          readOnly={readOnly}
          onChange={(e) =>
            setForm((p) => ({
              ...p,
              orderedPortions: e.target.value === '' ? '' : Number(e.target.value),
            }))
          }
        />
      </div>

      <div className={styles.checkInInlineRow}>
        <span className={styles.checkInInlineLabel}>מספר מנות משמחים:</span>
        <input
          type="number"
          min="0"
          className={styles.checkInInlineInput}
          value={form.entertainerPortions}
          readOnly={readOnly}
          onChange={(e) =>
            setForm((p) => ({
              ...p,
              entertainerPortions: e.target.value === '' ? '' : Number(e.target.value),
            }))
          }
        />
      </div>

      <div className={styles.checkInReserveSection}>
        {form.reserveTables.map((row) => (
          <div key={row.number} className={styles.checkInInlineRow}>
            <span className={styles.checkInInlineLabel}>
              הריני לאשר שפתחתי שולחן רזרבה מספר {row.number}:
            </span>
            <input
              type="text"
              className={styles.checkInInlineInput}
              value={row.value}
              readOnly={readOnly}
              onChange={(e) => handleReserveChange(row.number, e.target.value)}
            />
          </div>
        ))}
      </div>

      <div className={styles.checkInSpecialSection}>
        <p className={styles.checkInInlineLabel}>תוספות מיוחדות:</p>
        <input
          type="text"
          className={styles.checkInLineInput}
          value={form.specialAdditionLine1}
          readOnly={readOnly}
          onChange={(e) => setForm((p) => ({ ...p, specialAdditionLine1: e.target.value }))}
        />
        <input
          type="text"
          className={styles.checkInLineInput}
          value={form.specialAdditionLine2}
          readOnly={readOnly}
          onChange={(e) => setForm((p) => ({ ...p, specialAdditionLine2: e.target.value }))}
        />
      </div>

      <div className={`${styles.checkInField} ${styles.signatureSection}`}>
        <p className={styles.checkInInlineLabel}>חתימת הלקוח (חובה):</p>
        {readOnly && form.customerSignature ? (
          <img
            src={form.customerSignature}
            alt="חתימת הלקוח"
            className={styles.signaturePreview}
          />
        ) : readOnly ? (
          <p className={styles.checkInConfirmText}>לא נחתם</p>
        ) : (
          <>
            <div className={styles.signatureCanvasWrap}>
              <SignatureCanvas
                ref={sigCanvas}
                canvasProps={{ width: 400, height: 120, className: 'sigCanvas' }}
              />
            </div>
            <button
              type="button"
              className={styles.clearSigBtn}
              onClick={() => sigCanvas.current?.clear()}
            >
              נקה חתימה
            </button>
          </>
        )}
      </div>

      <div className={styles.checkInActions}>
        <button type="button" className={styles.checkInCancelBtn} onClick={onCancel}>
          סגירה
        </button>
        {!readOnly && (
          <button type="submit" className={styles.checkInSaveBtn} disabled={saving}>
            {saving ? 'שומר...' : 'שמירה'}
          </button>
        )}
      </div>
    </form>
  );
};

export default EventCheckInBoard;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { apiFetch } from '../../services/api';
import { API_URL } from '../../config/api';
import styles from './OptionActionModal.module.css';

interface Props {
  option: any;
  onClose: () => void;
  onSuccess: () => void;
}

const cancelReasonsList = [
  'יקר מדי',
  'תאריך לא הסתדר',
  'סגרו באולם אחר',
  'ביטול האירוע לחלוטין',
  'חוסר הסכמה על תנאים',
  'אחר'
];

const OptionActionModal = ({ option, onClose, onSuccess }: Props) => {
  const navigate = useNavigate();
  const [step, setStep] = useState<'choose' | 'cancelReason'>('choose');
  const [cancelReason, setCancelReason] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const eventDateStr = option.eventDate?.date
    ? new Date(option.eventDate.date).toLocaleDateString('he-IL')
    : '';

  const handleConvertToBooking = () => {
    onClose();
    navigate(`/booking/close-option/${option.id}`);
  };

  const handleConfirmCancel = async () => {
    if (!cancelReason) {
      alert('חובה לבחור סיבת ביטול עבור הסטטיסטיקה של המערכת.');
      return;
    }
    
    setIsSubmitting(true);
    try {
      const res = await apiFetch(`${API_URL}/bookings/release`, {
        method: 'POST',
        body: JSON.stringify({
          dateIds: [option.calendarDateId],
          cancelReason: cancelReason,
          clientName: option.clientAFullName,
        }),
      });
      const result = await res.json();
      if (result.success) { alert('האופציה בוטלה והסטטיסטיקה עודכנה.'); onSuccess(); }
      else alert(result.message);
    } catch { alert('שגיאת תקשורת.'); }
    finally { setIsSubmitting(false); }
  };

  return (
    <div className={styles.overlay} onClick={onClose}>
      <div className={styles.modal} onClick={e => e.stopPropagation()}>
        <div className={styles.header}>
          <span>{step === 'choose' ? 'ניהול אופציה' : 'פעולה על אופציה'} - {option.clientAFullName}</span>
          <button className={styles.closeBtn} onClick={onClose}>×</button>
        </div>

        {step === 'choose' && (
          <div className={styles.body}>
            <div className={styles.infoBox}>
              <div className={styles.infoRow}><label>תאריך:</label><span>{eventDateStr}</span></div>
              <div className={styles.infoRow}><label>סוג אירוע:</label><span>{option.eventType}</span></div>
              <div className={styles.infoRow}><label>זמן:</label><span>{option.timeOfDay}</span></div>
              <div className={styles.infoRow}><label>מוזמנים:</label><span>{option.guestCount}</span></div>
              <div className={styles.infoRow}><label>תשלום בסיסי:</label><span>₪{(option.basePrice ?? option.totalPrice)?.toLocaleString()}</span></div>
              {(option.extrasPrice ?? 0) > 0 && (
                <div className={styles.infoRow}><label>תוספות לאולם:</label><span>₪{option.extrasPrice?.toLocaleString()}</span></div>
              )}
              {(option.externalExtrasPrice ?? 0) > 0 && (
                <div className={styles.infoRow}><label>ספקים חיצוניים (לידיעה):</label><span>₪{option.externalExtrasPrice?.toLocaleString()}</span></div>
              )}
              <div className={styles.infoRow}><label>סה&quot;כ לאולם:</label><span style={{ fontWeight: 'bold' }}>₪{option.totalPrice?.toLocaleString()}</span></div>
              <div className={styles.infoRow}><label>טלפון:</label><span>{option.clientAPhone}</span></div>
            </div>
            <p className={styles.question}>בחר פעולה להמשך:</p>
            <div className={styles.actionButtons}>
              <button className={styles.finalizeBtn} onClick={handleConvertToBooking}>
                הפוך להזמנה סגורה (סגירת אירוע)
              </button>
              <button className={styles.cancelOptionBtn} onClick={() => setStep('cancelReason')}>
                בטל אופציה ושחרר תאריך
              </button>
            </div>
          </div>
        )}

        {step === 'cancelReason' && (
          <div className={styles.body}>
            <p className={styles.question} style={{ color: '#dc2626' }}>שימו לב: ביטול האופציה ישחרר את התאריך באופן מיידי.</p>
            <div className={styles.inputGroup} style={{ marginTop: '10px' }}>
              <label className={styles.inputLabel}>לצורך סטטיסטיקה, מדוע האופציה בוטלה?</label>
              <select 
                className={styles.input} 
                value={cancelReason} 
                onChange={(e) => setCancelReason(e.target.value)}
                style={{ cursor: 'pointer' }}
              >
                <option value="">בחרו סיבת ביטול מרכזית...</option>
                {cancelReasonsList.map(reason => (
                  <option key={reason} value={reason}>{reason}</option>
                ))}
              </select>
            </div>
            
            <div className={styles.footer} style={{ marginTop: '20px', padding: '0', border: 'none' }}>
              <button type="button" className={styles.backBtn} onClick={() => setStep('choose')}>חזור</button>
              <button 
                type="button" 
                className={styles.submitBtn} 
                style={{ background: '#dc2626' }}
                disabled={isSubmitting || !cancelReason}
                onClick={handleConfirmCancel}
              >
                {isSubmitting ? 'מבטל...' : 'אשר ביטול מוחלט'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default OptionActionModal;

import React from 'react';
import styles from './OptionsManager.module.css';
import OptionActionModal from '../OptionActionModal/OptionActionModal';
import NotifyOptionModal from '../NotifyOptionModal/NotifyOptionModal';
import { useBookingsQuery } from '../../hooks/queries';
import { apiFetch } from '../../services/api';
import { API_URL } from '../../config/api';
import { PageHeader } from '../ui/PageHeader';
import { Input } from '../ui/Input';
import { EmptyState } from '../ui/EmptyState';
import { calendarKeyFromDbDate } from '../../utils/dateLocal';

const HEBREW_NUMERALS: Record<number, string> = {
  1:'א',2:'ב',3:'ג',4:'ד',5:'ה',6:'ו',7:'ז',8:'ח',9:'ט',10:'י',
  11:'יא',12:'יב',13:'יג',14:'יד',15:'טו',16:'טז',17:'יז',18:'יח',19:'יט',20:'כ',
  21:'כא',22:'כב',23:'כג',24:'כד',25:'כה',26:'כו',27:'כז',28:'כח',29:'כט',30:'ל'
};

const getHebrewDateString = (dateObj: Date | null) => {
  if (!dateObj) return '';
  try {
    const formatter = new Intl.DateTimeFormat('he-IL-u-ca-hebrew', { day: 'numeric', month: 'long' });
    const fullString = formatter.format(dateObj);
    const parts = formatter.formatToParts(dateObj);
    const dayPart = parts.find(p => p.type === 'day')?.value;
    if (dayPart) {
      const hebLetter = HEBREW_NUMERALS[parseInt(dayPart, 10)];
      if (hebLetter) return fullString.replace(dayPart, hebLetter);
    }
    return fullString;
  } catch {
    return '';
  }
};

const OptionsManager = () => {
  const [search, setSearch] = React.useState('');
  const [selectedOption, setSelectedOption] = React.useState<any>(null);
  const [notifyOption, setNotifyOption] = React.useState<any>(null);

  const { data, isLoading: loading, refetch } = useBookingsQuery({ status: 'OPTION', limit: 100, page: 1 });

  const today = React.useMemo(() => {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }, []);

  const options = (data?.data ?? [])
    .filter((b: any) => {
      if (!b.isOption) return false;

      if (b.eventDate?.date) {
        const eventDay = new Date(b.eventDate.date);
        eventDay.setHours(0, 0, 0, 0);
        if (eventDay < today) return false;
      }

      if (!search) return true;
      return (
        b.clientAFullName?.includes(search) ||
        b.clientAIdNumber?.includes(search) ||
        b.clientBFullName?.includes(search) ||
        b.clientBIdNumber?.includes(search)
      );
    })
    .sort((a: any, b: any) => {
      const da = a.eventDate?.date ? new Date(a.eventDate.date).getTime() : 0;
      const db = b.eventDate?.date ? new Date(b.eventDate.date).getTime() : 0;
      return da - db;
    });

  const handleBump = async (bookingId: string) => {
    if (!window.confirm('האם לשלוח ללקוח התראת דחיפות ולקצר את הדד-ליין ל-3 שעות?')) return;
    try {
      const res = await apiFetch(`${API_URL}/bookings/bump`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ bookingId }),
      });
      const result = await res.json();
      if (result.success) {
        const lines = [result.message || 'הדד-ליין עודכן ל-3 שעות מעכשיו.'];
        if (result.emailSent) lines.push('נשלח במייל ✓');
        if (result.whatsappSent) lines.push('נשלח בוואטסאפ ✓');
        if (result.skippedReasons?.length) {
          lines.push('', 'שים לב:');
          lines.push(...result.skippedReasons);
        }
        alert(lines.join('\n'));
        refetch();
      } else {
        alert(result.message);
      }
    } catch {
      alert('שגיאה בהקפצת הלקוח.');
    }
  };

  if (loading) return <div className={styles.loading}>טוען נתונים...</div>;

  return (
    <div className={styles.container}>
      <PageHeader title="ניהול אופציות פעילות" subtitle="תאריכים שמורים הממתינים לסגירה" />

      <Input
        fieldClassName={styles.searchInput}
        placeholder="חיפוש לפי שם או תעודת זהות..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      {options.length === 0 ? (
        <EmptyState
          icon="⏳"
          title={search ? 'לא נמצאו תוצאות' : 'אין אופציות פעילות'}
          message={search ? 'נסה לחפש בשם אחר' : 'תאריכים באופציה יופיעו כאן'}
        />
      ) : (
        <div className={styles.grid}>
          {options.map((option: any) => {
            const dateObj = option.eventDate?.date ? new Date(option.eventDate.date) : null;
            const eventDateStr = dateObj ? dateObj.toLocaleDateString('he-IL') : '';
            const hebrewDateStr = getHebrewDateString(dateObj);
            const expiresAtStr = option.eventDate?.optionExpiresAt
              ? new Date(option.eventDate.optionExpiresAt).toLocaleString('he-IL')
              : 'לא מוגדר';

            return (
              <div key={option.id} className={styles.card} onClick={() => setSelectedOption(option)}>
                <div className={styles.cardContent}>
                  <div>
                    <h3 className={styles.eventDateText}>
                      תאריך אירוע: <strong>{eventDateStr}</strong>{' '}
                      <span style={{ color: '#d97706', fontSize: '0.95rem' }}>({hebrewDateStr})</span>
                    </h3>
                    <p className={styles.clientText}>לקוח: {option.clientAFullName} | טלפון: {option.clientAPhone}</p>
                    <p className={styles.expiryText}>פג תוקף ב: {expiresAtStr}</p>
                  </div>
                  <div className={styles.actions} onClick={(e) => e.stopPropagation()}>
                    <button
                      type="button"
                      onClick={() => setNotifyOption(option)}
                      className={`${styles.btn} ${styles.notifyBtn}`}
                    >
                      שלח הודעת עניין
                    </button>
                    <button type="button" onClick={() => handleBump(option.id)} className={`${styles.btn} ${styles.bumpBtn}`}>
                      הקפץ לקוח ⏱️
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedOption && (
        <OptionActionModal
          option={selectedOption}
          onClose={() => setSelectedOption(null)}
          onSuccess={() => { setSelectedOption(null); refetch(); }}
        />
      )}

      {notifyOption && (
        <NotifyOptionModal
          booking={notifyOption}
          eventDateStr={
            notifyOption.eventDate?.date
              ? calendarKeyFromDbDate(new Date(notifyOption.eventDate.date))
              : ''
          }
          onClose={() => setNotifyOption(null)}
        />
      )}
    </div>
  );
};

export default OptionsManager;

import React, { useEffect, useState } from 'react';
import { apiFetch } from '../../services/api';
import { API_URL } from '../../config/api';

const ROLE_LABELS: Record<string, string> = {
  manager: 'מנהל/ת',
  staff: 'מזכירות / מכירות',
  production: 'הפקה',
  floor_staff: 'צוות קבלה',
};

const ROLE_OPTIONS = Object.entries(ROLE_LABELS);

export const AuthorizedUsers = () => {
  const [users, setUsers] = useState<any[]>([]);
  const [email, setEmail] = useState('');
  const [newRole, setNewRole] = useState('manager');

  const AUTH_USERS_URL = `${API_URL}/auth/authorized-users`;

  const loadUsers = () => {
    apiFetch(AUTH_USERS_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`שגיאת שרת: ${res.status}`);
        return res.json();
      })
      .then((data) => setUsers(data))
      .catch((err) => console.error('שגיאה בטעינת משתמשים:', err));
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleAddEmail = async () => {
    const emailToSave = email.toLowerCase().trim();
    if (!emailToSave) return;

    try {
      const res = await apiFetch(AUTH_USERS_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: emailToSave, role: newRole }),
      });
      if (!res.ok) throw new Error('שגיאה בהוספה');
      setEmail('');
      loadUsers();
    } catch {
      alert('שגיאה בהוספת המייל - אולי הוא כבר קיים?');
    }
  };

  const handleRoleChange = async (id: string, role: string) => {
    try {
      const res = await apiFetch(`${AUTH_USERS_URL}/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role }),
      });
      if (!res.ok) throw new Error('שגיאה בעדכון תפקיד');
      loadUsers();
    } catch {
      alert('שגיאה בעדכון התפקיד');
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('האם את בטוחה שברצונך למחוק משתמש זה?')) return;
    try {
      const res = await apiFetch(`${AUTH_USERS_URL}/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('שגיאה במחיקה');
      loadUsers();
    } catch {
      alert('שגיאה במחיקת המייל');
    }
  };

  return (
    <div style={{
      background: '#fff',
      padding: '24px',
      borderRadius: '12px',
      boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
      marginTop: '20px',
    }}>
      <h3 style={{ marginTop: 0, marginBottom: '20px', color: '#2c3e50' }}>ניהול משתמשים מורשים</h3>

      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
        <input
          type="email"
          placeholder="הקלידי מייל של משתמש חדש..."
          value={email}
          onChange={(e) => setEmail(e.target.value.toLowerCase().trim())}
          style={{ flex: 1, minWidth: '200px', padding: '10px', borderRadius: '6px', border: '1px solid #ddd' }}
        />
        <select
          value={newRole}
          onChange={(e) => setNewRole(e.target.value)}
          style={{ padding: '10px', borderRadius: '6px', border: '1px solid #ddd' }}
          aria-label="תפקיד משתמש חדש"
        >
          {ROLE_OPTIONS.map(([value, label]) => (
            <option key={value} value={value}>{label}</option>
          ))}
        </select>
        <button
          onClick={handleAddEmail}
          style={{ padding: '10px 20px', background: '#4CAF50', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
        >
          הוסף
        </button>
      </div>

      <table style={{ width: '100%', textAlign: 'right', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #eee' }}>
            <th style={{ padding: '12px 8px', color: '#7f8c8d' }}>מייל מורשה</th>
            <th style={{ padding: '12px 8px', color: '#7f8c8d' }}>תפקיד</th>
            <th style={{ padding: '12px 8px', color: '#7f8c8d', width: '80px' }}>פעולות</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => (
            <tr key={user.id} style={{ borderBottom: '1px solid #f5f5f5' }}>
              <td style={{ padding: '12px 8px' }}>{user.email}</td>
              <td style={{ padding: '12px 8px' }}>
                <select
                  value={user.role || 'manager'}
                  onChange={(e) => handleRoleChange(user.id, e.target.value)}
                  style={{ padding: '6px', borderRadius: '4px', border: '1px solid #ddd' }}
                  aria-label={`תפקיד עבור ${user.email}`}
                >
                  {ROLE_OPTIONS.map(([value, label]) => (
                    <option key={value} value={value}>{label}</option>
                  ))}
                </select>
              </td>
              <td style={{ padding: '12px 8px' }}>
                <button
                  onClick={() => handleDelete(user.id)}
                  style={{ background: '#ff4757', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px' }}
                >
                  מחק
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

